196	function inversionsIn(list, truthOrder) {
197	  const pos = new Map(truthOrder.map((id, i) => [id, i]));
198	  let last = -1;
199	  let n = 0;
200	  for (const id of list) {
201	    if (!pos.has(id)) continue;
202	    if (pos.get(id) < last) n++;
