import { z } from 'zod';

// Every setting comes from the environment (contract B). Defaults match
// .env.example so a clean clone runs with no .env file. If <repo>/.env
// exists it is loaded first; real environment variables still win.
try {
  process.loadEnvFile(new URL('../../../../.env', import.meta.url));
} catch {
  // no .env file: defaults apply
}

const url = z.string().url();

const EnvSchema = z.object({
  NODE_ENV: z.enum(['development', 'production', 'test']).default('development'),
  PORT: z.coerce.number().int().positive().default(4000),
  WEB_ORIGIN: url.default('http://localhost:5173'),
  GRADER_TOKEN: z.string().min(1).default('grader-dev-token'),

  MONGO_URL: z.string().min(1).default('mongodb://localhost:27017/switchboard'),
  REDIS_URL: z.string().min(1).default('redis://localhost:6379'),
  ELASTICSEARCH_URL: url.default('http://localhost:9200'),

  PIGEON_URL: url.default('http://localhost:4010'),
  PIGEON_WEBHOOK_SECRET: z.string().min(1).default('whsec_pigeon_dev'),
  PIGEON_KEY_WS_ACME: z.string().min(1).default('pk_acme_7d1f0a'),
  PIGEON_KEY_WS_GLOBEX: z.string().min(1).default('pk_globex_c93b22'),

  OIDC_ISSUER: url.default('http://localhost:4020'),
  OIDC_CLIENT_ID: z.string().min(1).default('switchboard-web'),
  OIDC_CLIENT_SECRET: z.string().min(1).default('dev-secret-not-for-production'),
  OIDC_REDIRECT_URI: url.default('http://localhost:4000/auth/callback'),
});

const parsed = EnvSchema.safeParse(process.env);
if (!parsed.success) {
  // Fail fast with a readable message instead of a confusing runtime error later.
  const lines = parsed.error.issues.map((i) => `  ${i.path.join('.')}: ${i.message}`);
  console.error(`Invalid environment configuration:\n${lines.join('\n')}`);
  process.exit(1);
}
const e = parsed.data;

// Workspaces are whatever PIGEON_KEY_WS_<NAME> variables exist:
// PIGEON_KEY_WS_ACME -> ws_acme. Adding a workspace needs no code change.
function collectPigeonKeys(): Record<string, string> {
  const keys: Record<string, string> = {
    ws_acme: e.PIGEON_KEY_WS_ACME,
    ws_globex: e.PIGEON_KEY_WS_GLOBEX,
  };
  for (const [name, value] of Object.entries(process.env)) {
    const m = /^PIGEON_KEY_(WS_[A-Z0-9_]+)$/.exec(name);
    if (m && value) keys[m[1].toLowerCase()] = value;
  }
  return keys;
}

export const env = Object.freeze({
  nodeEnv: e.NODE_ENV,
  isProd: e.NODE_ENV === 'production',
  port: e.PORT,
  webOrigin: e.WEB_ORIGIN,
  graderToken: e.GRADER_TOKEN,
  mongoUrl: e.MONGO_URL,
  redisUrl: e.REDIS_URL,
  elasticsearchUrl: e.ELASTICSEARCH_URL,
  pigeon: Object.freeze({
    url: e.PIGEON_URL,
    webhookSecret: e.PIGEON_WEBHOOK_SECRET,
    apiKeys: Object.freeze(collectPigeonKeys()),
  }),
  oidc: Object.freeze({
    issuer: e.OIDC_ISSUER,
    clientId: e.OIDC_CLIENT_ID,
    clientSecret: e.OIDC_CLIENT_SECRET,
    redirectUri: e.OIDC_REDIRECT_URI,
  }),
});

export const isKnownWorkspace = (ws: string): boolean => Object.hasOwn(env.pigeon.apiKeys, ws);

// Tunables in one place. Values are chosen against PIGEON.md and harness/check.js.

export const WEBHOOK = Object.freeze({
  /** Signatures older (or further in the future) than this are rejected with 401. */
  toleranceSeconds: 5 * 60,
  bodyLimit: '256kb',
});

export const OUTBOX = Object.freeze({
  /** Pigeon sometimes answers after 12 s; give up earlier and retry with the same Idempotency-Key. */
  sendTimeoutMs: 8_000,
  /** Must exceed sendTimeoutMs so a live worker never loses its lease mid-request. */
  leaseMs: 20_000,
  pollIntervalMs: 250,
  batchSize: 10,
  backoffBaseMs: 500,
  backoffMaxMs: 5_000,
});

export const RATE_LIMIT = Object.freeze({
  /** Pigeon: bucket of 8 refilling at 4/s per workspace. Stay just under. */
  bucketSize: 8,
  refillPerSecond: 3.5,
  /** Pause after a 503 so an outage is not hammered. */
  unavailablePauseMs: 1_000,
});

export const SESSION = Object.freeze({
  cookieName: 'sb_sid',
  ttlSeconds: 8 * 60 * 60,
  loginStateTtlSeconds: 10 * 60,
});

export const PAGINATION = Object.freeze({
  defaultLimit: 25,
  maxLimit: 100,
});

/** Every Redis key this app owns starts with this, so reset never touches anything else. */
export const REDIS_PREFIX = 'sb:';

export const SHUTDOWN_TIMEOUT_MS = 5_000;

// The message catalog: every API outcome has one code, one HTTP status and one
// default message. Controllers and services refer to codes, never to raw
// strings or status numbers.

export const MSG = {
  // ---- success
  OK: { status: 200, message: 'OK.' },
  CREATED: { status: 201, message: 'Created.' },
  ACCEPTED: { status: 202, message: 'Accepted.' },
  CONVERSATIONS_LISTED: { status: 200, message: 'Conversations fetched.' },
  MESSAGES_LISTED: { status: 200, message: 'Messages fetched.' },
  REPLY_QUEUED: { status: 202, message: 'Reply queued for delivery.' },
  CONVERSATION_CLAIMED: { status: 200, message: 'Conversation claimed.' },
  CONVERSATION_RELEASED: { status: 200, message: 'Conversation released.' },
  CONVERSATION_CLOSED: { status: 200, message: 'Conversation closed.' },
  CONVERSATION_REOPENED: { status: 200, message: 'Conversation reopened.' },
  RESET_DONE: { status: 200, message: 'All application data deleted.' },

  // ---- client errors
  VALIDATION_FAILED: { status: 400, message: 'Request is invalid.' },
  UNAUTHENTICATED: { status: 401, message: 'Sign in required.' },
  INVALID_GRADER_TOKEN: { status: 401, message: 'Missing or invalid grader token.' },
  FORBIDDEN_WORKSPACE: { status: 403, message: 'You are not a member of this workspace.' },
  FORBIDDEN_ROLE: { status: 403, message: 'Your role does not allow this action.' },
  ROUTE_NOT_FOUND: { status: 404, message: 'Route not found.' },
  WORKSPACE_NOT_FOUND: { status: 404, message: 'Workspace not found.' },
  CONVERSATION_NOT_FOUND: { status: 404, message: 'Conversation not found.' },
  CONVERSATION_TAKEN: { status: 409, message: 'Another agent already holds this conversation.' },
  PAYLOAD_TOO_LARGE: { status: 413, message: 'Request body is too large.' },

  // ---- webhook (PIGEON.md: never 5xx for a bad request)
  WEBHOOK_BAD_SIGNATURE: { status: 401, message: 'Invalid signature.' },
  WEBHOOK_STALE: { status: 401, message: 'Timestamp outside the accepted window.' },
  WEBHOOK_BAD_BODY: { status: 400, message: 'Body could not be parsed.' },

  // ---- server
  SERVICE_UNAVAILABLE: { status: 503, message: 'Service is starting or shutting down.' },
  INTERNAL_ERROR: { status: 500, message: 'Something went wrong.' },
} as const satisfies Record<string, { status: number; message: string }>;

export type MsgCode = keyof typeof MSG;

// Roles come from the IdP `workspaces` claim. Permissions are listed per
// action so a check reads `can(role, 'conversation.reassign')`, not role names.

export const ROLES = ['admin', 'agent'] as const;
export type Role = (typeof ROLES)[number];

export const PERMISSIONS = {
  'conversation.read': ['admin', 'agent'],
  'conversation.reply': ['admin', 'agent'],
  'conversation.claim': ['admin', 'agent'],
  'conversation.close': ['admin', 'agent'],
  /** Release or take over a conversation held by someone else. */
  'conversation.reassign': ['admin'],
} as const satisfies Record<string, readonly Role[]>;

export type Permission = keyof typeof PERMISSIONS;

export const can = (role: Role, permission: Permission): boolean =>
  (PERMISSIONS[permission] as readonly Role[]).includes(role);

import { hostname } from 'node:os';
import { randomBytes } from 'node:crypto';

// One id per process. Shows up in every log line and is used as the outbox
// lease owner, so "which copy did this" is always answerable.
export const instanceId = `${hostname()}-${process.pid}-${randomBytes(3).toString('hex')}`;

type Level = 'debug' | 'info' | 'warn' | 'error';
type Fields = Record<string, unknown>;

const order: Record<Level, number> = { debug: 10, info: 20, warn: 30, error: 40 };
const minLevel = (process.env.LOG_LEVEL as Level) in order ? (process.env.LOG_LEVEL as Level) : 'info';

function serializeError(err: unknown) {
  if (err instanceof Error) return { name: err.name, message: err.message, stack: err.stack };
  return err;
}

function write(level: Level, msg: string, fields?: Fields) {
  if (order[level] < order[minLevel]) return;
  const line: Fields = { t: new Date().toISOString(), level, instance: instanceId, msg, ...fields };
  if (line.err) line.err = serializeError(line.err);
  (level === 'error' || level === 'warn' ? process.stderr : process.stdout).write(JSON.stringify(line) + '\n');
}

export interface Logger {
  debug(msg: string, fields?: Fields): void;
  info(msg: string, fields?: Fields): void;
  warn(msg: string, fields?: Fields): void;
  error(msg: string, fields?: Fields): void;
  child(bound: Fields): Logger;
}

function make(bound: Fields): Logger {
  return {
    debug: (m, f) => write('debug', m, { ...bound, ...f }),
    info: (m, f) => write('info', m, { ...bound, ...f }),
    warn: (m, f) => write('warn', m, { ...bound, ...f }),
    error: (m, f) => write('error', m, { ...bound, ...f }),
    child: (more) => make({ ...bound, ...more }),
  };
}

export const logger = make({});

import { MongoClient, type Db } from 'mongodb';
import { env } from '../config/env.js';
import { logger } from './logger.js';

let client: MongoClient | undefined;
let db: Db | undefined;

export async function connectMongo(): Promise<Db> {
  if (db) return db;
  client = new MongoClient(env.mongoUrl, {
    serverSelectionTimeoutMS: 5_000,
    maxPoolSize: 50,
    // Every acknowledged write is on disk before we answer 2xx (crash safety, level 2).
    writeConcern: { w: 'majority', journal: true },
  });
  await client.connect();
  db = client.db();
  await db.command({ ping: 1 });
  logger.info('mongo connected', { db: db.databaseName });
  return db;
}

/** The connected database. Throws if called before connectMongo() so misuse is loud. */
export function getDb(): Db {
  if (!db) throw new Error('MongoDB is not connected yet; call connectMongo() during boot');
  return db;
}

export async function pingMongo(): Promise<boolean> {
  try {
    await getDb().command({ ping: 1 });
    return true;
  } catch {
    return false;
  }
}

export async function closeMongo(): Promise<void> {
  await client?.close();
  client = undefined;
  db = undefined;
}

/** E11000: the unique index already holds this document, which for us means "already stored". */
export const isDuplicateKeyError = (err: unknown): boolean =>
  typeof err === 'object' && err !== null && (err as { code?: number }).code === 11000;

import { Redis } from 'ioredis';
import { env } from '../config/env.js';
import { REDIS_PREFIX } from '../config/constants.js';
import { logger } from './logger.js';

// Two connections: a connection in SUBSCRIBE mode cannot run normal
// commands, so pub/sub gets its own.
let command: Redis | undefined;
let subscriber: Redis | undefined;

function create(name: string): Redis {
  const r = new Redis(env.redisUrl, {
    connectionName: `switchboard-${name}`,
    maxRetriesPerRequest: 3,
    enableReadyCheck: true,
    lazyConnect: true,
  });
  r.on('error', (err) => logger.warn('redis error', { conn: name, err }));
  return r;
}

export async function connectRedis(): Promise<Redis> {
  if (command) return command;
  command = create('cmd');
  await command.connect();
  await command.ping();
  logger.info('redis connected');
  return command;
}

export function getRedis(): Redis {
  if (!command) throw new Error('Redis is not connected yet; call connectRedis() during boot');
  return command;
}

/** Lazily opened connection reserved for SUBSCRIBE / PSUBSCRIBE. */
export async function getSubscriber(): Promise<Redis> {
  if (!subscriber) {
    subscriber = create('sub');
    await subscriber.connect();
  }
  return subscriber;
}

export async function pingRedis(): Promise<boolean> {
  try {
    return (await getRedis().ping()) === 'PONG';
  } catch {
    return false;
  }
}

export async function closeRedis(): Promise<void> {
  await Promise.allSettled([command?.quit(), subscriber?.quit()]);
  command = undefined;
  subscriber = undefined;
}

/** Builds an app-owned key: rkey('rl', 'ws_acme') -> "sb:rl:ws_acme". */
export const rkey = (...parts: string[]): string => REDIS_PREFIX + parts.join(':');

import { SHUTDOWN_TIMEOUT_MS } from '../config/constants.js';
import { logger } from './logger.js';

// Readiness + ordered shutdown. Modules register a stop hook when they start;
// hooks run in reverse order (last started, first stopped).

type Hook = { name: string; fn: () => Promise<void> | void };
const hooks: Hook[] = [];
let ready = false;
let stopping = false;

export const isReady = (): boolean => ready && !stopping;
export const markReady = (): void => {
  ready = true;
};

export function onShutdown(name: string, fn: Hook['fn']): void {
  hooks.push({ name, fn });
}

export async function shutdown(reason: string, code = 0): Promise<never> {
  if (stopping) return new Promise<never>(() => {});
  stopping = true;
  logger.info('shutting down', { reason });

  const force = setTimeout(() => {
    logger.error('shutdown timed out, exiting');
    process.exit(code || 1);
  }, SHUTDOWN_TIMEOUT_MS);
  force.unref();

  for (const hook of [...hooks].reverse()) {
    try {
      await hook.fn();
      logger.debug('stopped', { hook: hook.name });
    } catch (err) {
      logger.warn('stop hook failed', { hook: hook.name, err });
    }
  }
  process.exit(code);
}

export function installSignalHandlers(): void {
  process.once('SIGTERM', () => void shutdown('SIGTERM'));
  process.once('SIGINT', () => void shutdown('SIGINT'));
  process.on('unhandledRejection', (err) => logger.error('unhandled rejection', { err }));
  process.on('uncaughtException', (err) => {
    logger.error('uncaught exception', { err });
    void shutdown('uncaughtException', 1);
  });
}

import { MSG, type MsgCode } from '../constants/messages.js';

export interface FieldError {
  path: string;
  message: string;
}

/**
 * The only error type services throw on purpose. The error middleware turns it
 * into the response envelope, using the status and message from the catalog.
 *
 *   throw new AppError('CONVERSATION_TAKEN');
 *   throw new AppError('VALIDATION_FAILED', { errors: [{ path: 'text', message: 'Required' }] });
 */
export class AppError extends Error {
  readonly code: MsgCode;
  readonly status: number;
  readonly errors?: FieldError[];
  readonly data?: unknown;

  constructor(code: MsgCode, opts: { message?: string; errors?: FieldError[]; data?: unknown; cause?: unknown } = {}) {
    super(opts.message ?? MSG[code].message, { cause: opts.cause });
    this.name = 'AppError';
    this.code = code;
    this.status = MSG[code].status;
    this.errors = opts.errors;
    this.data = opts.data;
  }
}

export const isAppError = (err: unknown): err is AppError => err instanceof AppError;

import type { Response } from 'express';
import { MSG, type MsgCode } from '../constants/messages.js';
import type { FieldError } from './AppError.js';

// Two kinds of response:
//  - envelope: every route we design ourselves
//  - raw:      routes whose exact shape is fixed by BRIEF.md / PIGEON.md
//              (/healthz, /api/me, /__grader/*, /webhooks/pigeon)

export interface SuccessEnvelope<T> {
  success: true;
  code: MsgCode;
  message: string;
  data: T;
  meta?: Record<string, unknown>;
  requestId: string;
}

export interface ErrorEnvelope {
  success: false;
  code: MsgCode;
  message: string;
  errors?: FieldError[];
  requestId: string;
}

const requestIdOf = (res: Response): string => res.req?.requestId ?? 'unknown';

export const respond = {
  ok<T>(res: Response, code: MsgCode, data: T, opts: { meta?: Record<string, unknown>; message?: string } = {}) {
    const body: SuccessEnvelope<T> = {
      success: true,
      code,
      message: opts.message ?? MSG[code].message,
      data,
      ...(opts.meta ? { meta: opts.meta } : {}),
      requestId: requestIdOf(res),
    };
    return res.status(MSG[code].status).json(body);
  },

  fail(res: Response, code: MsgCode, opts: { errors?: FieldError[]; message?: string } = {}) {
    const body: ErrorEnvelope = {
      success: false,
      code,
      message: opts.message ?? MSG[code].message,
      ...(opts.errors?.length ? { errors: opts.errors } : {}),
      requestId: requestIdOf(res),
    };
    return res.status(MSG[code].status).json(body);
  },

  /** Contract routes: exact body, no envelope. */
  raw(res: Response, status: number, body: unknown) {
    return res.status(status).json(body);
  },

  /** Contract routes that only need a status code (and a tiny body for humans). */
  status(res: Response, code: MsgCode) {
    return res.status(MSG[code].status).json({ code });
  },
};

import type { NextFunction, Request, RequestHandler, Response } from 'express';

/** Express 4 does not catch rejected promises; this forwards them to the error middleware. */
export const asyncHandler =
  <Req extends Request = Request>(fn: (req: Req, res: Response, next: NextFunction) => Promise<unknown>): RequestHandler =>
  (req, res, next) => {
    fn(req as Req, res, next).catch(next);
  };

import { createHash, randomBytes, timingSafeEqual } from 'node:crypto';

/** Constant-time string comparison; false for different lengths without leaking timing on content. */
export function safeEqual(a: string, b: string): boolean {
  const ab = Buffer.from(a);
  const bb = Buffer.from(b);
  if (ab.length !== bb.length) return false;
  return timingSafeEqual(ab, bb);
}

export const randomToken = (bytes = 32): string => randomBytes(bytes).toString('base64url');

export const sha256 = (input: string | Buffer): Buffer => createHash('sha256').update(input).digest();

import { randomBytes } from 'node:crypto';

/** Short, sortable-enough, prefixed id: newId('req') -> "req_lx3k9a_4f1c2b8e". */
export const newId = (prefix: string): string =>
  `${prefix}_${Date.now().toString(36)}_${randomBytes(4).toString('hex')}`;

import type { Role } from '../constants/roles.js';

export interface WorkspaceMembership {
  id: string;
  role: Role;
}

export interface SessionUser {
  sub: string;
  name?: string;
  email?: string;
  workspaces: WorkspaceMembership[];
}

declare global {
  namespace Express {
    interface Request {
      requestId: string;
      /** Set by requireSession. */
      user?: SessionUser;
      /** Set by requireMember: the workspace this request acts on, and the caller's role in it. */
      workspace?: WorkspaceMembership;
      /** Set by the raw-body parser on the webhook route, for HMAC verification. */
      rawBody?: Buffer;
    }
  }
}

import type { RequestHandler } from 'express';
import { newId } from '../utils/ids.js';

const SAFE = /^[A-Za-z0-9_\-.:]{1,64}$/;

/** Reuses an incoming x-request-id if it looks sane, otherwise makes one, and echoes it back. */
export const requestId: RequestHandler = (req, res, next) => {
  const incoming = req.get('x-request-id');
  req.requestId = incoming && SAFE.test(incoming) ? incoming : newId('req');
  res.setHeader('x-request-id', req.requestId);
  next();
};

import type { RequestHandler } from 'express';
import { logger } from '../infra/logger.js';

const QUIET = new Set(['/healthz']);

/** One line per request once the response is finished. */
export const requestLogger: RequestHandler = (req, res, next) => {
  if (QUIET.has(req.path)) return next();
  const start = process.hrtime.bigint();
  res.on('finish', () => {
    const ms = Number(process.hrtime.bigint() - start) / 1e6;
    const level = res.statusCode >= 500 ? 'error' : res.statusCode >= 400 ? 'warn' : 'info';
    logger[level]('http', {
      reqId: req.requestId,
      method: req.method,
      path: req.path,
      status: res.statusCode,
      ms: Math.round(ms * 10) / 10,
    });
  });
  next();
};

import type { RequestHandler } from 'express';

/** A small, dependency-free subset of what helmet sets; enough for a JSON API. */
export const securityHeaders: RequestHandler = (_req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Referrer-Policy', 'no-referrer');
  res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
  next();
};

import type { RequestHandler } from 'express';
import { env } from '../config/env.js';
import { safeEqual } from '../utils/crypto.js';
import { respond } from '../utils/respond.js';

/** Contract D: /__grader/* needs x-grader-token === GRADER_TOKEN, otherwise 401. */
export const requireGraderToken: RequestHandler = (req, res, next) => {
  const token = req.get('x-grader-token');
  if (!token || !safeEqual(token, env.graderToken)) return respond.status(res, 'INVALID_GRADER_TOKEN');
  next();
};

import type { RequestHandler } from 'express';
import type { ZodType } from 'zod';

export interface ValidationSchemas {
  body?: ZodType;
  query?: ZodType;
  params?: ZodType;
}

/**
 * Parses body / query / params with zod and replaces them with the parsed
 * (coerced, defaulted, stripped) values. A failure throws the ZodError, which
 * the error middleware turns into 400 VALIDATION_FAILED with field errors.
 *
 *   router.post('/x', validate({ body: ReplySchema }), controller.reply)
 */
export const validate =
  (schemas: ValidationSchemas): RequestHandler =>
  (req, _res, next) => {
    try {
      if (schemas.params) req.params = schemas.params.parse(req.params) as typeof req.params;
      if (schemas.query) req.query = schemas.query.parse(req.query) as typeof req.query;
      if (schemas.body) req.body = schemas.body.parse(req.body ?? {});
      next();
    } catch (err) {
      next(err);
    }
  };

import express, { type RequestHandler } from 'express';
import { WEBHOOK } from '../config/constants.js';

/**
 * For webhook routes only: keep the exact bytes Pigeon signed. Any content
 * type is accepted, because a forged request may lie about it and must still
 * reach the signature check (and get 401, not 415).
 */
export const rawBody: RequestHandler[] = [
  express.raw({ type: () => true, limit: WEBHOOK.bodyLimit }),
  (req, _res, next) => {
    req.rawBody = Buffer.isBuffer(req.body) ? req.body : Buffer.alloc(0);
    next();
  },
];

import type { RequestHandler } from 'express';
import { respond } from '../utils/respond.js';

export const notFound: RequestHandler = (_req, res) => {
  respond.fail(res, 'ROUTE_NOT_FOUND');
};

import type { ErrorRequestHandler } from 'express';
import { ZodError } from 'zod';
import { logger } from '../infra/logger.js';
import { isAppError, type FieldError } from '../utils/AppError.js';
import { respond } from '../utils/respond.js';

const zodToFieldErrors = (err: ZodError): FieldError[] =>
  err.issues.map((i) => ({ path: i.path.join('.') || '(root)', message: i.message }));

/** body-parser errors carry a `type` and a `status`. */
interface BodyParserError {
  type?: string;
  status?: number;
}

/**
 * The single place errors become responses. Known errors map to catalog codes.
 * Anything else is logged with its stack and answered as 500 without details.
 */
export const errorHandler: ErrorRequestHandler = (err, req, res, _next) => {
  if (res.headersSent) {
    req.socket.destroy();
    return;
  }

  if (isAppError(err)) {
    if (err.status >= 500) logger.error('app error', { reqId: req.requestId, code: err.code, err });
    return respond.fail(res, err.code, { errors: err.errors, message: err.message });
  }

  if (err instanceof ZodError) {
    return respond.fail(res, 'VALIDATION_FAILED', { errors: zodToFieldErrors(err) });
  }

  const bp = err as BodyParserError;
  if (bp?.type === 'entity.parse.failed') {
    return respond.fail(res, 'VALIDATION_FAILED', { errors: [{ path: '(body)', message: 'Malformed JSON' }] });
  }
  if (bp?.type === 'entity.too.large') return respond.fail(res, 'PAYLOAD_TOO_LARGE');

  logger.error('unhandled error', { reqId: req.requestId, method: req.method, path: req.path, err });
  return respond.fail(res, 'INTERNAL_ERROR');
};

import type { Request, Response } from 'express';
import { isReady } from '../infra/lifecycle.js';
import { instanceId } from '../infra/logger.js';
import { pingMongo } from '../infra/mongo.js';
import { pingRedis } from '../infra/redis.js';
import { respond } from '../utils/respond.js';

// Contract route: the check polls it and waits for 200. Raw shape, no envelope.
export const healthController = {
  /** Liveness + readiness: 200 only once boot finished and both stores answer. */
  async healthz(_req: Request, res: Response) {
    if (!isReady()) return respond.raw(res, 503, { ok: false, reason: 'starting' });
    const [mongo, redis] = await Promise.all([pingMongo(), pingRedis()]);
    const ok = mongo && redis;
    return respond.raw(res, ok ? 200 : 503, { ok, mongo, redis, instance: instanceId });
  },
};

import { Router } from 'express';
import { healthController } from '../controllers/health.controller.js';
import { asyncHandler } from '../utils/asyncHandler.js';

export const healthRoutes = Router();

healthRoutes.get('/healthz', asyncHandler(healthController.healthz));

import { Router } from 'express';
import { healthRoutes } from './health.routes.js';

/**
 * Routes that take JSON bodies. Mounted after express.json().
 * Planned (added after the API design discussion):
 *   /auth/*        auth.routes.ts
 *   /api/*         me.routes.ts, conversation.routes.ts
 *   /__grader/*    grader.routes.ts (requireGraderToken)
 */
export const jsonRoutes = Router();
jsonRoutes.use(healthRoutes);

/**
 * Routes that need the exact raw bytes (HMAC). Mounted BEFORE express.json().
 *   POST /webhooks/pigeon   webhook.routes.ts (rawBody)
 */
export const rawRoutes = Router();

import express, { type Express } from 'express';
import cookieParser from 'cookie-parser';
import { errorHandler } from './middleware/errorHandler.js';
import { notFound } from './middleware/notFound.js';
import { requestId } from './middleware/requestId.js';
import { requestLogger } from './middleware/requestLogger.js';
import { securityHeaders } from './middleware/securityHeaders.js';
import { jsonRoutes, rawRoutes } from './routes/index.js';

/** Builds the Express app. No I/O here, so tests can create it without a server. */
export function createApp(): Express {
  const app = express();

  app.disable('x-powered-by');
  app.set('trust proxy', 'loopback'); // the check's load balancer and Vite's proxy run on localhost

  // 1. cross-cutting
  app.use(requestId);
  app.use(requestLogger);
  app.use(securityHeaders);
  app.use(cookieParser());

  // 2. raw-body routes (webhooks) must see the bytes before any JSON parser
  app.use(rawRoutes);

  // 3. JSON routes
  app.use(express.json({ limit: '100kb' }));
  app.use(jsonRoutes);

  // 4. fallthrough
  app.use(notFound);
  app.use(errorHandler);

  return app;
}

import type { Db, IndexDescription } from 'mongodb';
import { logger } from '../infra/logger.js';

/**
 * All indexes, declared next to the collections that own them. Created at boot
 * before /healthz turns green. createIndexes is idempotent and safe to run
 * from several instances at once.
 *
 * The collections and their indexes are filled in after the schema discussion
 * (see ARCHITECTURE.md §5): conversations, messages, events, counters.
 */
export const COLLECTIONS = {
  conversations: 'conversations',
  messages: 'messages',
  events: 'events',
  counters: 'counters',
} as const;

export const INDEXES: Record<string, IndexDescription[]> = {
  // e.g. [COLLECTIONS.conversations]: [{ key: { workspace: 1, contact: 1 }, unique: true, name: 'uniq_ws_contact' }],
};

export async function ensureIndexes(db: Db): Promise<void> {
  for (const [collection, specs] of Object.entries(INDEXES)) {
    if (specs.length) await db.collection(collection).createIndexes(specs);
  }
  logger.info('indexes ensured', { collections: Object.keys(INDEXES).length });
}

import { createServer } from 'node:http';
import { env } from './config/env.js';
import { createApp } from './app.js';
import { installSignalHandlers, markReady, onShutdown } from './infra/lifecycle.js';
import { instanceId, logger } from './infra/logger.js';
import { closeMongo, connectMongo } from './infra/mongo.js';
import { closeRedis, connectRedis } from './infra/redis.js';
import { ensureIndexes } from './repositories/indexes.js';

// Boot order: listen early (so /healthz answers 503 "starting" instead of
// connection refused), then connect stores, ensure indexes, start background
// work, and only then report ready.
async function main() {
  installSignalHandlers();

  const app = createApp();
  const server = createServer(app);
  server.keepAliveTimeout = 65_000; // outlive typical proxy idle timeouts

  await new Promise<void>((resolve, reject) => {
    server.once('error', reject);
    server.listen(env.port, resolve);
  });
  logger.info('listening', { port: env.port, env: env.nodeEnv, instance: instanceId });
  onShutdown('http', () => new Promise<void>((r) => server.close(() => r())));

  const db = await connectMongo();
  onShutdown('mongo', closeMongo);
  await connectRedis();
  onShutdown('redis', closeRedis);

  await ensureIndexes(db);

  // Next phases register here: realtime gateway (attach to `server`), outbox worker.

  markReady();
  logger.info('ready', { workspaces: Object.keys(env.pigeon.apiKeys) });
}

main().catch((err) => {
  logger.error('boot failed', { err });
  process.exit(1);
});

