// Shapes the frontend works with. They mirror the API contract in
// FRONTEND_ARCHITECTURE.md §7 and are the only place those shapes are declared.

export type Role = 'admin' | 'agent';

export interface WorkspaceMembership {
  id: string;
  role: Role;
}

export interface Me {
  sub: string;
  name?: string;
  email?: string;
  workspaces: WorkspaceMembership[];
}

export type ConversationState = 'open' | 'closed';

export interface Conversation {
  contact: string;
  state: ConversationState;
  assignee: string | null;
  lastActivityAt: string;
  lastMessage?: { text: string; dir: MessageDirection; at: string } | null;
}

export type MessageDirection = 'in' | 'out';
export type DeliveryStatus = 'queued' | 'sent' | 'delivered' | 'failed';

export interface Message {
  /** Server id; for an optimistic reply it is `local:<clientRef>` until the server answers. */
  id: string;
  dir: MessageDirection;
  text: string;
  occurredAt: string;
  /** Pigeon message id (inbound) */
  providerId?: string | null;
  /** Our idempotency key (outbound) */
  clientRef?: string | null;
  status?: DeliveryStatus | null;
  authorSub?: string | null;
  /** Client-only: the POST has not been acknowledged yet. */
  pending?: boolean;
  /** Client-only: every POST attempt failed; the user can retry with the same clientRef. */
  submitFailed?: boolean;
}

export type InboxFilter = 'open' | 'mine' | 'closed' | 'all';
export const INBOX_FILTERS: readonly InboxFilter[] = ['open', 'mine', 'closed', 'all'];

export interface Page<T> {
  items: T[];
  nextCursor?: string | null;
  prevCursor?: string | null;
}

import type { DeliveryStatus, Message } from './types';

// Pure rules for a conversation's message list. No React, fully unit-tested.

const STATUS_RANK: Record<DeliveryStatus, number> = { queued: 0, sent: 1, delivered: 2, failed: 2 };

/** Status only moves forward: a late "sent" never overwrites "delivered". */
export function nextStatus(current: DeliveryStatus | null | undefined, incoming: DeliveryStatus): DeliveryStatus {
  if (!current) return incoming;
  return STATUS_RANK[incoming] > STATUS_RANK[current] ? incoming : current;
}

/** Stable identity of a message across optimistic, server and socket copies. */
export function messageKey(m: Pick<Message, 'id' | 'clientRef' | 'providerId'>): string {
  if (m.clientRef) return `ref:${m.clientRef}`;
  if (m.providerId) return `pm:${m.providerId}`;
  return `id:${m.id}`;
}

export function compareMessages(a: Message, b: Message): number {
  const t = Date.parse(a.occurredAt) - Date.parse(b.occurredAt);
  if (t !== 0) return t;
  return messageKey(a) < messageKey(b) ? -1 : messageKey(a) > messageKey(b) ? 1 : 0;
}

/**
 * Merge incoming messages into a list: dedupe by identity, keep the furthest
 * status, prefer server fields over optimistic ones, and sort oldest first.
 */
export function mergeMessages(existing: readonly Message[], incoming: readonly Message[]): Message[] {
  const byKey = new Map<string, Message>();
  for (const m of existing) byKey.set(messageKey(m), m);
  for (const m of incoming) {
    const key = messageKey(m);
    const prev = byKey.get(key);
    if (!prev) {
      byKey.set(key, m);
      continue;
    }
    const status = m.status ? nextStatus(prev.status, m.status) : prev.status;
    const fromServer = !m.pending;
    byKey.set(key, {
      ...prev,
      ...m,
      id: fromServer && !m.id.startsWith('local:') ? m.id : prev.id,
      status,
      pending: fromServer ? false : prev.pending,
      submitFailed: fromServer ? false : m.submitFailed ?? prev.submitFailed,
    });
  }
  return [...byKey.values()].sort(compareMessages);
}

/** Apply a delivery status to the message with this clientRef. Returns the same array if nothing changed. */
export function applyStatus(list: readonly Message[], clientRef: string, status: DeliveryStatus): readonly Message[] {
  let changed = false;
  const out = list.map((m) => {
    if (m.clientRef !== clientRef) return m;
    const s = nextStatus(m.status, status);
    if (s === m.status) return m;
    changed = true;
    return { ...m, status: s };
  });
  return changed ? out : list;
}

import type { Conversation, Role } from './types';

// Mirrors server/src/constants/roles.ts. The UI only hides or disables; the server enforces.

const PERMISSIONS = {
  'conversation.read': ['admin', 'agent'],
  'conversation.reply': ['admin', 'agent'],
  'conversation.claim': ['admin', 'agent'],
  'conversation.close': ['admin', 'agent'],
  'conversation.reassign': ['admin'],
} as const satisfies Record<string, readonly Role[]>;

export type Permission = keyof typeof PERMISSIONS;

export const can = (role: Role, permission: Permission): boolean =>
  (PERMISSIONS[permission] as readonly Role[]).includes(role);

export interface ConversationAbilities {
  canReply: boolean;
  canClaim: boolean;
  canRelease: boolean;
  canClose: boolean;
  canReopen: boolean;
  /** Why the composer is disabled, if it is. */
  replyBlockedReason?: string;
}

/** Every button on a conversation is derived here, in one testable place. */
export function conversationAbilities(c: Conversation, me: string, role: Role): ConversationAbilities {
  const mine = c.assignee === me;
  const free = c.assignee === null;
  const admin = can(role, 'conversation.reassign');
  const heldByOther = !free && !mine;

  return {
    canReply: can(role, 'conversation.reply') && (!heldByOther || admin),
    canClaim: can(role, 'conversation.claim') && (free || (heldByOther && admin)),
    canRelease: (mine && can(role, 'conversation.claim')) || (heldByOther && admin),
    canClose: c.state === 'open' && can(role, 'conversation.close') && (mine || free || admin),
    canReopen: c.state === 'closed' && can(role, 'conversation.close'),
    replyBlockedReason: heldByOther && !admin ? `Held by ${c.assignee}. Claim is not available.` : undefined,
  };
}

