    const b = (body ?? {}) as Partial<{ code: string; message: string; errors: FieldError[]; requestId: string }>;
    if (res.status === 401) unauthorizedListeners.forEach((fn) => fn());
    throw new ApiError({
      status: res.status,
      code: b.code ?? `HTTP_${res.status}`,
      message: b.message ?? res.statusText ?? 'Request failed.',
      errors: b.errors,
      requestId: b.requestId ?? res.headers.get('x-request-id') ?? undefined,
    });
  }
  return { res, body };
}

export const http = {
  /** Envelope routes: returns { data, meta, code, message }. */
  async request<T>(path: string, opts: RequestOptions = {}): Promise<Envelope<T>> {
    const { body } = await send(path, opts);
    const env = (body ?? {}) as Partial<Envelope<T>> & { success?: boolean };
    return { data: env.data as T, meta: env.meta, code: env.code ?? 'OK', message: env.message ?? '' };
  },

  /** Contract routes with a fixed raw shape (e.g. /api/me). */
  async raw<T>(path: string, opts: RequestOptions = {}): Promise<T> {
    const { body } = await send(path, opts);
    return body as T;
  },

  get: <T>(path: string, query?: Query, signal?: AbortSignal) => http.request<T>(path, { query, signal }),
  post: <T>(path: string, body?: unknown, query?: Query) => http.request<T>(path, { method: 'POST', body: body ?? {}, query }),
};

export const enc = encodeURIComponent;

import type { InboxFilter } from '../domain/types';

// One factory for every cache key, so realtime patches and features agree.
export const qk = {
  me: ['me'] as const,
  workspace: (ws: string) => ['ws', ws] as const,
  conversationsAll: (ws: string) => ['ws', ws, 'conversations'] as const,
  conversations: (ws: string, filter: InboxFilter) => ['ws', ws, 'conversations', filter] as const,
  conversation: (ws: string, contact: string) => ['ws', ws, 'conversation', contact] as const,
  messages: (ws: string, contact: string) => ['ws', ws, 'messages', contact] as const,
};

// sessionStorage can be missing or throw (private mode, blocked storage).
// Everything here is a convenience; the app works without it.

export const session = {
  get(key: string): string | null {
    try {
      return window.sessionStorage.getItem(key);
    } catch {
      return null;
    }
  },
  set(key: string, value: string): void {
    try {
      window.sessionStorage.setItem(key, value);
    } catch {
      /* ignore */
    }
  },
  remove(key: string): void {
    try {
      window.sessionStorage.removeItem(key);
    } catch {
      /* ignore */
    }
  },
};

const rtf = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' });
const timeFmt = new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' });
const dateFmt = new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric' });

/** "just now", "5 min ago", "3 h ago", then a date. */
export function relativeTime(iso: string, now = Date.now()): string {
  const t = Date.parse(iso);
  if (Number.isNaN(t)) return '';
  const s = Math.round((t - now) / 1000);
  if (Math.abs(s) < 45) return 'just now';
  const m = Math.round(s / 60);
  if (Math.abs(m) < 60) return rtf.format(m, 'minute');
  const h = Math.round(m / 60);
  if (Math.abs(h) < 24) return rtf.format(h, 'hour');
  return dateFmt.format(t);
}

export const clockTime = (iso: string): string => {
  const t = Date.parse(iso);
  return Number.isNaN(t) ? '' : timeFmt.format(t);
};

/** Idempotency key for a reply. Created once per message, reused on every retry. */
export const newClientRef = (): string =>
  typeof crypto !== 'undefined' && 'randomUUID' in crypto
    ? crypto.randomUUID()
    : `ref-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;

// UI text for server error codes (server/src/constants/messages.ts). Falls back
// to the server's own message, then to a generic line.

const BY_CODE: Record<string, string> = {
  NETWORK_ERROR: 'You appear to be offline. We will keep trying.',
  UNAUTHENTICATED: 'Your session has ended. Please sign in again.',
  FORBIDDEN_WORKSPACE: 'You do not have access to this workspace.',
  FORBIDDEN_ROLE: 'Your role does not allow this action.',
  CONVERSATION_TAKEN: 'Another agent claimed this conversation first.',
  CONVERSATION_NOT_FOUND: 'This conversation no longer exists.',
  VALIDATION_FAILED: 'Please check what you entered.',
  INTERNAL_ERROR: 'Something went wrong on our side. Please try again.',
};

export function messageFor(err: unknown): string {
  if (err && typeof err === 'object') {
    const e = err as { code?: string; message?: string };
    if (e.code && BY_CODE[e.code]) return BY_CODE[e.code];
    if (e.message) return e.message;
  }
  return 'Something went wrong.';
}

export const UI = {
  appName: 'Switchboard',
  signInTitle: 'Sign in to your team inbox',
  signInButton: 'Continue with company sign-in',
  emptyInbox: 'No conversations here yet.',
  pickConversation: 'Select a conversation to start.',
  emptyThread: 'No messages yet. Say hello.',
  composerPlaceholder: 'Write a reply… (Enter to send, Shift+Enter for a new line)',
  notSent: 'Not sent',
  retry: 'Retry',
  loadOlder: 'Load older messages',
  loadMore: 'Load more',
  noAccess: 'You are not a member of this workspace.',
};

