import type { Conversation, Message, Page } from '../domain/types';
import { applyStatus, mergeMessages } from '../domain/messages';

// Structural twin of TanStack's InfiniteData, so these helpers stay React-free and testable.
export interface Paged<T> {
  pages: Page<T>[];
  pageParams: unknown[];
}

/**
 * Messages are loaded newest page first (pages[0] = latest, older pages follow).
 * New messages always land in pages[0]; an id already in any page is merged in place.
 */
export function upsertMessages(data: Paged<Message> | undefined, incoming: Message[]): Paged<Message> | undefined {
  if (!data) return data;
  const pages = data.pages.map((p) => ({ ...p }));
  const rest: Message[] = [];
  for (const m of incoming) {
    const idx = pages.findIndex((p) => mergeMessages(p.items, []).some((x) => sameMessage(x, m)));
    if (idx >= 0) pages[idx].items = mergeMessages(pages[idx].items, [m]);
    else rest.push(m);
  }
  if (rest.length) {
    if (!pages.length) pages.push({ items: [] });
    pages[0].items = mergeMessages(pages[0].items, rest);
  }
  return { ...data, pages };
}

function sameMessage(a: Message, b: Message): boolean {
  if (a.clientRef && b.clientRef) return a.clientRef === b.clientRef;
  if (a.providerId && b.providerId) return a.providerId === b.providerId;
  return a.id === b.id;
}

export function patchMessageStatus(
  data: Paged<Message> | undefined,
  clientRef: string,
  status: NonNullable<Message['status']>,
): Paged<Message> | undefined {
  if (!data) return data;
  let changed = false;
  const pages = data.pages.map((p) => {
    const items = applyStatus(p.items, clientRef, status);
    if (items === p.items) return p;
    changed = true;
    return { ...p, items: [...items] };
  });
  return changed ? { ...data, pages } : data;
}

export function patchMessage(data: Paged<Message> | undefined, clientRef: string, patch: Partial<Message>): Paged<Message> | undefined {
  if (!data) return data;
  return {
    ...data,
    pages: data.pages.map((p) => ({ ...p, items: p.items.map((m) => (m.clientRef === clientRef ? { ...m, ...patch } : m)) })),
  };
}

/** Flatten newest-first pages into one oldest-first list for rendering. */
export function flattenMessages(data: Paged<Message> | undefined): Message[] {
  if (!data) return [];
  return mergeMessages([], [...data.pages].reverse().flatMap((p) => p.items));
}

export function patchConversationInPages(
  data: Paged<Conversation> | undefined,
  contact: string,
  patch: Partial<Conversation>,
): Paged<Conversation> | undefined {
  if (!data) return data;
  let changed = false;
  const pages = data.pages.map((p) => ({
    ...p,
    items: p.items.map((c) => {
      if (c.contact !== contact) return c;
      changed = true;
      return { ...c, ...patch };
    }),
  }));
  return changed ? { ...data, pages } : data;
}

import type { Conversation, ConversationState, DeliveryStatus, Message } from '../domain/types';

// Socket frames (contract F) and the pure translation into cache actions.
// The provider executes the actions; this file decides them, and is tested.

export interface Frame {
  seq: number;
  type: string;
  contact?: string;
  message_id?: string;
  client_ref?: string;
  status?: DeliveryStatus;
  assignee?: string | null;
  state?: ConversationState;
  /** Optional full message, so the UI can render without a refetch. */
  message?: Message;
}

export type FrameAction =
  | { kind: 'upsertMessage'; contact: string; message: Message }
  | { kind: 'invalidateMessages'; contact: string }
  | { kind: 'patchStatus'; contact: string; clientRef: string; status: DeliveryStatus }
  | { kind: 'patchConversation'; contact: string; patch: Partial<Conversation> }
  | { kind: 'refreshList' };

const STATUSES = new Set<DeliveryStatus>(['queued', 'sent', 'delivered', 'failed']);

export function parseFrame(raw: string): Frame | null {
  try {
    const f = JSON.parse(raw) as Partial<Frame>;
    if (!f || typeof f.seq !== 'number' || typeof f.type !== 'string') return null;
    return f as Frame;
  } catch {
    return null;
  }
}

export function frameToActions(f: Frame): FrameAction[] {
  const contact = f.contact;
  switch (f.type) {
    case 'message.inbound':
    case 'message.outbound': {
      if (!contact) return [{ kind: 'refreshList' }];
      const msg: FrameAction = f.message
        ? { kind: 'upsertMessage', contact, message: f.message }
        : { kind: 'invalidateMessages', contact };
      return [msg, { kind: 'refreshList' }];
    }
    case 'message.status': {
      if (!contact || !f.client_ref || !f.status || !STATUSES.has(f.status)) return [];
      return [{ kind: 'patchStatus', contact, clientRef: f.client_ref, status: f.status }];
    }
    case 'conversation.assigned': {
      if (!contact) return [{ kind: 'refreshList' }];
      return [{ kind: 'patchConversation', contact, patch: { assignee: f.assignee ?? null } }, { kind: 'refreshList' }];
    }
    case 'conversation.state': {
      if (!contact || (f.state !== 'open' && f.state !== 'closed')) return [{ kind: 'refreshList' }];
      return [{ kind: 'patchConversation', contact, patch: { state: f.state } }, { kind: 'refreshList' }];
    }
    default:
      // Unknown event types: the server added something; refreshing keeps us correct.
      return [{ kind: 'refreshList' }];
  }
}

import { session } from '../lib/storage';
import { parseFrame, type Frame } from './frames';

export type ConnectionStatus = 'connecting' | 'open' | 'reconnecting' | 'offline' | 'stopped';

interface Options {
  workspace: string;
  onFrame: (frame: Frame) => void;
  onStatus: (status: ConnectionStatus) => void;
  /** Called on (re)open. `replayed` is false on a cold start (no lastSeq), so the caller should refetch. */
  onOpen?: (info: { replayed: boolean }) => void;
  /** Called after repeated failures; resolve false if the session is gone, to stop retrying. */
  checkSession?: () => Promise<boolean>;
}

const MIN_DELAY = 500;
const MAX_DELAY = 10_000;

/**
 * One WebSocket per workspace that:
 *  - resumes with ?after=<lastSeq> so nothing is missed across drops or reloads
 *  - ignores frames it has already seen (seq <= lastSeq)
 *  - reconnects with exponential backoff + jitter, immediately when the
 *    browser comes back online or the tab becomes visible
 */
export class RealtimeConnection {
  private ws: WebSocket | null = null;
  private lastSeq: number | null;
  private attempts = 0;
  private timer: ReturnType<typeof setTimeout> | null = null;
  private stopped = false;
  private readonly storageKey: string;

  constructor(private readonly opts: Options) {
    this.storageKey = `sb:lastSeq:${opts.workspace}`;
    const stored = Number(session.get(this.storageKey));
    this.lastSeq = Number.isFinite(stored) && stored > 0 ? stored : null;
  }

  start(): void {
    this.stopped = false;
    window.addEventListener('online', this.wake);
    window.addEventListener('offline', this.markOffline);
    document.addEventListener('visibilitychange', this.onVisibility);
    this.connect();
  }

  stop(): void {
    this.stopped = true;
    window.removeEventListener('online', this.wake);
    window.removeEventListener('offline', this.markOffline);
    document.removeEventListener('visibilitychange', this.onVisibility);
    if (this.timer) clearTimeout(this.timer);
    this.timer = null;
    const ws = this.ws;
    this.ws = null;
    if (ws && ws.readyState <= WebSocket.OPEN) ws.close(1000, 'client stop');
    this.opts.onStatus('stopped');
  }

  private url(): string {
    const proto = window.location.protocol === 'https:' ? 'wss' : 'ws';
    const qs = new URLSearchParams({ workspace: this.opts.workspace });
    if (this.lastSeq !== null) qs.set('after', String(this.lastSeq));
    return `${proto}://${window.location.host}/ws?${qs}`;
  }

  private connect(): void {
    if (this.stopped) return;
    if (!navigator.onLine) return this.markOffline();
    this.opts.onStatus(this.attempts === 0 ? 'connecting' : 'reconnecting');

    const replayed = this.lastSeq !== null;
    const ws = new WebSocket(this.url());
    this.ws = ws;

    ws.onopen = () => {
      if (this.ws !== ws) return;
      this.attempts = 0;
      this.opts.onStatus('open');
      this.opts.onOpen?.({ replayed });
    };

    ws.onmessage = (ev) => {
      if (this.ws !== ws || typeof ev.data !== 'string') return;
      const frame = parseFrame(ev.data);
      if (!frame) return;
      if (this.lastSeq !== null && frame.seq <= this.lastSeq) return; // already applied
      this.lastSeq = frame.seq;
      session.set(this.storageKey, String(frame.seq));
      this.opts.onFrame(frame);
    };

    ws.onclose = () => {
      if (this.ws !== ws) return;
      this.ws = null;
      this.scheduleReconnect();
    };
    // onerror is always followed by onclose; nothing to do here.
  }

  private scheduleReconnect(): void {
    if (this.stopped) return;
    this.attempts++;
    this.opts.onStatus(navigator.onLine ? 'reconnecting' : 'offline');

    const base = Math.min(MAX_DELAY, MIN_DELAY * 2 ** (this.attempts - 1));
    const delay = base / 2 + Math.random() * (base / 2);

    this.timer = setTimeout(async () => {
      this.timer = null;
      // A refused upgrade looks like a plain close; after a few, ask whether we are still signed in.
      if (this.attempts >= 3 && this.opts.checkSession && !(await this.opts.checkSession())) return this.stop();
      this.connect();
    }, delay);
  }

  private wake = (): void => {
    if (this.stopped || (this.ws && this.ws.readyState <= WebSocket.OPEN)) return;
    if (this.timer) clearTimeout(this.timer);
    this.timer = null;
    this.attempts = 0;
    this.connect();
  };

  private markOffline = (): void => {
    if (!this.stopped) this.opts.onStatus('offline');
  };

  private onVisibility = (): void => {
    if (document.visibilityState === 'visible') this.wake();
  };
}

