import { ApiError, http } from '../../lib/http';
import type { Me } from '../../domain/types';

export const authApi = {
  /** Contract route (raw shape). A 401 means "not signed in", which is a normal state, not an error. */
  async me(): Promise<Me | null> {
    try {
      return await http.raw<Me>('/api/me');
    } catch (err) {
      if (err instanceof ApiError && err.status === 401) return null;
      throw err;
    }
  },

  logout: () => http.raw<unknown>('/auth/logout', { method: 'POST', body: {} }),

  /** Full-page navigation: the server builds the PKCE request and redirects to the IdP. */
  loginUrl: (returnTo?: string) => (returnTo ? `/auth/login?returnTo=${encodeURIComponent(returnTo)}` : '/auth/login'),
};

import { useQuery } from '@tanstack/react-query';
import { qk } from '../../lib/queryKeys';
import { authApi } from './api';

export function useMe() {
  return useQuery({
    queryKey: qk.me,
    queryFn: authApi.me,
    staleTime: 5 * 60_000,
    retry: (count, err) => count < 2 && (err as { retryable?: boolean }).retryable !== false,
  });
}

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useNavigate } from 'react-router';
import { session } from '../../lib/storage';
import { qk } from '../../lib/queryKeys';
import { authApi } from './api';

export function useLogout() {
  const qc = useQueryClient();
  const navigate = useNavigate();
  return useMutation({
    mutationFn: authApi.logout,
    onSettled: () => {
      // Whatever the server said, forget everything about this user locally.
      qc.clear();
      qc.setQueryData(qk.me, null);
      for (const ws of ['ws_acme', 'ws_globex']) session.remove(`sb:lastSeq:${ws}`);
      navigate('/login', { replace: true });
    },
  });
}

import { Navigate, Outlet, useLocation } from 'react-router';
import { messageFor } from '../../constants/uiMessages';
import { Button } from '../../shared/ui/Button';
import { EmptyState } from '../../shared/ui/EmptyState';
import { FullPageSpinner } from '../../shared/ui/Spinner';
import { useMe } from './useMe';

/** Route guard: renders children only with a session; otherwise sends the user to /login. */
export function RequireAuth() {
  const me = useMe();
  const location = useLocation();

  if (me.isPending) return <FullPageSpinner label="Checking your session" />;
  if (me.isError)
    return (
      <div className="center-fill">
        <EmptyState title={messageFor(me.error)}>
          <Button variant="primary" onClick={() => me.refetch()}>
            Try again
          </Button>
        </EmptyState>
      </div>
    );
  if (!me.data) return <Navigate to="/login" replace state={{ from: location.pathname }} />;
  return <Outlet />;
}

