// sessionStorage can be missing or throw (private mode, blocked storage).
// Everything here is a convenience; the app works without it.

export const session = {
  get(key: string): string | null {
    try {
      return window.sessionStorage.getItem(key);
    } catch {
      return null;
    }
  },
  set(key: string, value: string): void {
    try {
      window.sessionStorage.setItem(key, value);
    } catch {
      /* ignore */
    }
  },
  remove(key: string): void {
    try {
      window.sessionStorage.removeItem(key);
    } catch {
      /* ignore */
    }
  },
};

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useNavigate } from 'react-router';
import { session } from '../../lib/storage';
import { qk } from '../../lib/queryKeys';
import { authApi } from './api';

export function useLogout() {
  const qc = useQueryClient();
  const navigate = useNavigate();
  return useMutation({
    mutationFn: authApi.logout,
    onSettled: () => {
      // Whatever the server said, forget everything about this user locally.
      qc.clear();
      qc.setQueryData(qk.me, null);
      for (const ws of ['ws_acme', 'ws_globex']) session.remove(`sb:lastSeq:${ws}`);
      navigate('/login', { replace: true });
    },
  });
}

