import { useState, type FormEvent, type KeyboardEvent } from 'react';
import { UI } from '../../constants/uiMessages';
import { Button } from '../../shared/ui/Button';

const MAX_LEN = 2000;

interface Props {
  onSend: (text: string) => void;
