import { enc, http } from '../../lib/http';
import type { Conversation, Message, Page } from '../../domain/types';

export type ConversationAction = 'claim' | 'release' | 'close' | 'reopen';

const base = (contact: string) => `/api/conversations/${enc(contact)}`;

export const conversationApi = {
  async get(workspace: string, contact: string, signal?: AbortSignal): Promise<Conversation> {
    return (await http.get<Conversation>(base(contact), { workspace }, signal)).data;
  },

  /** Newest page first; `before` walks back in time. Items inside a page are oldest first. */
  async messages(workspace: string, contact: string, before: string | undefined, signal?: AbortSignal): Promise<Page<Message>> {
    const res = await http.get<{ items: Message[] }>(`${base(contact)}/messages`, { workspace, before, limit: 50 }, signal);
    return { items: res.data?.items ?? [], prevCursor: (res.meta?.prevCursor as string | null | undefined) ?? null };
  },

  /** Idempotent on clientRef: safe to call again after a timeout or network error. */
  async reply(workspace: string, contact: string, text: string, clientRef: string): Promise<Message | undefined> {
    return (await http.post<Message | undefined>(`${base(contact)}/replies`, { text, client_ref: clientRef }, { workspace })).data;
  },

  async act(workspace: string, contact: string, action: ConversationAction): Promise<Conversation> {
    return (await http.post<Conversation>(`${base(contact)}/${action}`, {}, { workspace })).data;
  },
};

import { useQuery } from '@tanstack/react-query';
import { qk } from '../../lib/queryKeys';
import { conversationApi } from './api';

export function useConversation(workspace: string, contact: string) {
  return useQuery({
    queryKey: qk.conversation(workspace, contact),
    queryFn: ({ signal }) => conversationApi.get(workspace, contact, signal),
  });
}

import { useInfiniteQuery } from '@tanstack/react-query';
import { useMemo } from 'react';
import { flattenMessages } from '../../lib/cache';
import { qk } from '../../lib/queryKeys';
import { conversationApi } from './api';

/** pages[0] is the newest page; fetchNextPage loads OLDER messages (lib/cache.ts relies on this). */
export function useMessages(workspace: string, contact: string) {
  const query = useInfiniteQuery({
    queryKey: qk.messages(workspace, contact),
    queryFn: ({ pageParam, signal }) => conversationApi.messages(workspace, contact, pageParam, signal),
    initialPageParam: undefined as string | undefined,
    getNextPageParam: (last) => last.prevCursor ?? undefined,
  });

  const messages = useMemo(() => flattenMessages(query.data), [query.data]);
  return { ...query, messages };
}

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useCallback } from 'react';
import { ApiError } from '../../lib/http';
import { patchMessage, upsertMessages, type Paged } from '../../lib/cache';
import { newClientRef } from '../../lib/ids';
import { qk } from '../../lib/queryKeys';
import type { Message } from '../../domain/types';
import { messageFor } from '../../constants/uiMessages';
import { useToast } from '../../shared/toast/ToastProvider';
import { conversationApi } from './api';

interface Vars {
  text: string;
  clientRef: string;
}

/**
 * Sending a reply, safely:
 *  1. the clientRef is created once, before the first attempt
 *  2. the message appears at once (optimistic, "queued")
 *  3. network errors / 5xx retry with the SAME clientRef (server dedupes)
 *  4. if all attempts fail, the bubble offers "Retry", again with the same clientRef
 */
export function useReply(workspace: string, contact: string, sub: string) {
  const qc = useQueryClient();
  const toast = useToast();
  const key = qk.messages(workspace, contact);

  const mutation = useMutation({
    mutationFn: ({ text, clientRef }: Vars) => conversationApi.reply(workspace, contact, text, clientRef),
    retry: (count, err) => count < 3 && (!(err instanceof ApiError) || err.retryable),
    retryDelay: (attempt) => Math.min(4_000, 500 * 2 ** attempt),

    onMutate: async ({ text, clientRef }) => {
      await qc.cancelQueries({ queryKey: key });
      const optimistic: Message = {
        id: `local:${clientRef}`,
        dir: 'out',
        text,
        clientRef,
        occurredAt: new Date().toISOString(),
        status: 'queued',
        authorSub: sub,
        pending: true,
        submitFailed: false,
      };
      qc.setQueryData<Paged<Message>>(key, (d) =>
        upsertMessages(d ?? { pages: [{ items: [] }], pageParams: [undefined] }, [optimistic]),
      );
    },

    onSuccess: (serverMsg, { clientRef }) => {
      qc.setQueryData<Paged<Message>>(key, (d) =>
        serverMsg ? upsertMessages(d, [{ ...serverMsg, pending: false }]) : patchMessage(d, clientRef, { pending: false }),
      );
      void qc.invalidateQueries({ queryKey: qk.conversationsAll(workspace) });
    },

    onError: (err, { clientRef }) => {
      qc.setQueryData<Paged<Message>>(key, (d) => patchMessage(d, clientRef, { pending: false, submitFailed: true }));
      toast.error(messageFor(err));
    },
  });

  const send = useCallback((text: string) => mutation.mutate({ text, clientRef: newClientRef() }), [mutation]);

  const retry = useCallback(
    (m: Message) => {
      if (!m.clientRef) return;
      qc.setQueryData<Paged<Message>>(key, (d) => patchMessage(d, m.clientRef!, { pending: true, submitFailed: false }));
      mutation.mutate({ text: m.text, clientRef: m.clientRef });
    },
    [mutation, qc, key],
  );

  return { send, retry, isSending: mutation.isPending };
}

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { ApiError } from '../../lib/http';
import { patchConversationInPages, type Paged } from '../../lib/cache';
import { qk } from '../../lib/queryKeys';
import type { Conversation } from '../../domain/types';
import { messageFor } from '../../constants/uiMessages';
import { useToast } from '../../shared/toast/ToastProvider';
import { conversationApi, type ConversationAction } from './api';

const DONE: Record<ConversationAction, string> = {
  claim: 'You now hold this conversation.',
  release: 'Conversation released.',
  close: 'Conversation closed.',
  reopen: 'Conversation reopened.',
};

/** Claim / release / close / reopen. Not optimistic: the server decides who wins a claim race. */
export function useConversationActions(workspace: string, contact: string) {
  const qc = useQueryClient();
  const toast = useToast();

  return useMutation({
    mutationFn: (action: ConversationAction) => conversationApi.act(workspace, contact, action),
    onSuccess: (conv, action) => {
      if (conv) {
        qc.setQueryData<Conversation>(qk.conversation(workspace, contact), conv);
        qc.setQueriesData<Paged<Conversation>>({ queryKey: qk.conversationsAll(workspace) }, (d) =>
          patchConversationInPages(d, contact, conv),
        );
      }
      void qc.invalidateQueries({ queryKey: qk.conversationsAll(workspace) });
      toast.success(DONE[action]);
    },
    onError: (err) => {
      toast.error(messageFor(err));
      // Lost a race (409) or stale view: show the truth.
      if (err instanceof ApiError && (err.status === 409 || err.status === 404)) {
        void qc.invalidateQueries({ queryKey: qk.conversation(workspace, contact) });
      }
    },
  });
}

import { Link, useLocation } from 'react-router';
import { conversationAbilities } from '../../domain/permissions';
import type { Conversation, Role } from '../../domain/types';
import { Button } from '../../shared/ui/Button';
import type { ConversationAction } from './api';
import { useConversationActions } from './useConversationActions';

interface Props {
  conversation: Conversation;
  workspace: string;
  sub: string;
  role: Role;
}

export function ConversationHeader({ conversation: c, workspace, sub, role }: Props) {
  const act = useConversationActions(workspace, c.contact);
  const ab = conversationAbilities(c, sub, role);
  const location = useLocation();
  const backTo = `/w/${encodeURIComponent(workspace)}${location.search}`;

  const busy = (a: ConversationAction) => act.isPending && act.variables === a;
  const holder = c.assignee === null ? 'Unassigned' : c.assignee === sub ? 'Assigned to you' : `Assigned to ${c.assignee}`;

  return (
    <header className="convhead">
      <Link to={backTo} className="convhead__back" aria-label="Back to inbox">
        ←
      </Link>
      <div className="convhead__who">
        <h2 className="convhead__contact">{c.contact}</h2>
        <p className="convhead__sub">
          {holder} · {c.state === 'open' ? 'Open' : 'Closed'}
        </p>
      </div>
      <div className="convhead__actions">
        {ab.canClaim && (
          <Button variant="primary" size="sm" onClick={() => act.mutate('claim')} loading={busy('claim')} disabled={act.isPending}>
            {c.assignee && c.assignee !== sub ? 'Take over' : 'Claim'}
          </Button>
        )}
        {ab.canRelease && (
          <Button size="sm" onClick={() => act.mutate('release')} loading={busy('release')} disabled={act.isPending}>
            Release
          </Button>
        )}
        {ab.canClose && (
          <Button size="sm" onClick={() => act.mutate('close')} loading={busy('close')} disabled={act.isPending}>
            Close
          </Button>
        )}
        {ab.canReopen && (
          <Button size="sm" onClick={() => act.mutate('reopen')} loading={busy('reopen')} disabled={act.isPending}>
            Reopen
          </Button>
        )}
      </div>
    </header>
  );
}

import clsx from 'clsx';
import { memo } from 'react';
import { UI } from '../../constants/uiMessages';
import type { Message } from '../../domain/types';
import { clockTime } from '../../lib/time';
import { StatusBadge } from '../../shared/ui/StatusBadge';

interface Props {
  m: Message;
  onRetry: (m: Message) => void;
}

export const MessageBubble = memo(function MessageBubble({ m, onRetry }: Props) {
  const out = m.dir === 'out';
  return (
    <li className={clsx('msg', out ? 'msg--out' : 'msg--in', m.pending && 'msg--pending')}>
      <div className="msg__bubble">
        <p className="msg__text">{m.text}</p>
        <div className="msg__meta">
          <time dateTime={m.occurredAt}>{clockTime(m.occurredAt)}</time>
          {out && !m.submitFailed && m.status && <StatusBadge status={m.status} />}
          {out && m.submitFailed && (
            <span className="msg__failed">
              {UI.notSent} ·{' '}
              <button type="button" className="linkbtn" onClick={() => onRetry(m)}>
                {UI.retry}
              </button>
            </span>
          )}
        </div>
      </div>
    </li>
  );
});

import { useLayoutEffect, useRef } from 'react';
import { UI } from '../../constants/uiMessages';
import type { Message } from '../../domain/types';
import { Button } from '../../shared/ui/Button';
import { EmptyState } from '../../shared/ui/EmptyState';
import { MessageBubble } from './MessageBubble';

interface Props {
  messages: Message[];
  hasOlder: boolean;
  loadingOlder: boolean;
  onLoadOlder: () => void;
  onRetry: (m: Message) => void;
}

const NEAR_BOTTOM_PX = 120;

/** Sticks to the bottom when new messages arrive, unless the agent scrolled up to read history. */
export function MessageList({ messages, hasOlder, loadingOlder, onLoadOlder, onRetry }: Props) {
  const ref = useRef<HTMLDivElement>(null);
  const stick = useRef(true);
  const prevHeight = useRef(0);
  const prevFirst = useRef<string | undefined>(undefined);

  const onScroll = () => {
    const el = ref.current;
    if (el) stick.current = el.scrollHeight - el.scrollTop - el.clientHeight < NEAR_BOTTOM_PX;
  };

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const first = messages[0]?.id;
    if (prevFirst.current && first !== prevFirst.current && !stick.current) {
      // Older messages were prepended: keep the view where it was.
      el.scrollTop += el.scrollHeight - prevHeight.current;
    } else if (stick.current) {
      el.scrollTop = el.scrollHeight;
    }
    prevFirst.current = first;
    prevHeight.current = el.scrollHeight;
  }, [messages]);

  return (
    <div className="thread" ref={ref} onScroll={onScroll}>
      {hasOlder && (
        <div className="center-pad">
          <Button size="sm" variant="ghost" onClick={onLoadOlder} loading={loadingOlder}>
            {UI.loadOlder}
          </Button>
        </div>
      )}
      {messages.length === 0 ? (
        <EmptyState title={UI.emptyThread} />
      ) : (
        <ol className="thread__list" role="log" aria-live="polite" aria-relevant="additions">
          {messages.map((m) => (
            <MessageBubble key={m.clientRef ?? m.providerId ?? m.id} m={m} onRetry={onRetry} />
          ))}
        </ol>
      )}
    </div>
  );
}

