/* ---------- base ---------- */
*,
*::before,
*::after {
  box-sizing: border-box;
}
html,
body,
#root {
  height: 100%;
}
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: var(--fs-md) / 1.45 var(--font-sans);
  -webkit-font-smoothing: antialiased;
}
h1,
h2,
p {
  margin: 0;
}
a {
  color: var(--accent);
}
:focus-visible {
  outline: none;
  box-shadow: var(--focus);
  border-radius: var(--radius-sm);
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
.center-fill {
  display: grid;
  place-items: center;
  height: 100%;
  padding: var(--space-5);
}
.center-pad {
  display: flex;
  justify-content: center;
  padding: var(--space-3);
}

/* ---------- primitives ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  font: inherit;
  font-weight: 500;
  cursor: pointer;
  text-decoration: none;
  white-space: nowrap;
  transition: background 0.15s, border-color 0.15s;
}
.btn:hover:not(:disabled) {
  background: var(--surface-2);
}
.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}
.btn--sm {
  padding: 4px 10px;
  font-size: var(--fs-sm);
}
.btn--md {
  padding: 8px 16px;
}
.btn--primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-text);
}
.btn--primary:hover:not(:disabled) {
  background: var(--accent);
  filter: brightness(1.08);
}
.btn--ghost {
  background: transparent;
  border-color: transparent;
}
.btn--danger {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}
.linkbtn {
  border: 0;
  background: none;
  padding: 0;
  color: inherit;
  font: inherit;
  text-decoration: underline;
  cursor: pointer;
}

.spinner {
  display: inline-block;
  border: 2px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .spinner {
    animation-duration: 2.4s;
  }
}

.empty {
  text-align: center;
  color: var(--text-muted);
  padding: var(--space-5);
}
.empty__title {
  font-size: var(--fs-lg);
  color: var(--text);
}
.empty__body {
  margin-top: var(--space-3);
}

.pill {
  display: inline-block;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: var(--fs-xs);
  background: var(--surface-2);
  color: var(--text);
}
.pill--muted {
  color: var(--text-muted);
}
.pill--accent {
  background: var(--accent-soft);
  color: var(--accent);
}

.status {
  font-size: var(--fs-xs);
  white-space: nowrap;
}
.status--failed {
  color: var(--danger);
  font-weight: 600;
}

.conn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--fs-sm);
  color: var(--text-muted);
}
.conn__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--warn);
}
.conn--open .conn__dot {
  background: var(--success);
}
.conn--offline .conn__dot,
.conn--stopped .conn__dot {
  background: var(--danger);
}

.banner {
  grid-area: banner;
  padding: var(--space-2) var(--space-4);
  font-size: var(--fs-sm);
}
.banner--warn {
  background: var(--warn-soft);
  color: var(--warn);
}

.toasts {
  position: fixed;
  right: var(--space-4);
  bottom: var(--space-4);
  display: grid;
  gap: var(--space-2);
  z-index: 50;
  max-width: min(420px, calc(100vw - 32px));
}
.toast {
  display: flex;
  align-items: start;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-md);
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-md);
}
.toast--error {
  border-color: var(--danger);
  background: var(--danger-soft);
}
.toast--success {
  border-color: var(--success);
  background: var(--success-soft);
}
.toast__close {
  margin-left: auto;
  border: 0;
  background: none;
  color: inherit;
