/* Design tokens. Components use only these variables, so theming is one place. */
:root {
  color-scheme: light dark;

  --font-sans: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-mono: ui-monospace, 'SFMono-Regular', Menlo, Consolas, monospace;

  --fs-xs: 12px;
  --fs-sm: 13px;
  --fs-md: 14px;
  --fs-lg: 16px;
  --fs-xl: 20px;

  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;

  --bg: #f6f7f9;
  --surface: #ffffff;
  --surface-2: #f0f2f5;
  --border: #e3e6eb;
  --text: #16191d;
  --text-muted: #5f6873;
  --accent: #2f5bea;
  --accent-text: #ffffff;
  --accent-soft: #e6ecfd;
  --danger: #c7362f;
  --danger-soft: #fbe9e8;
  --success: #1f8a4c;
  --success-soft: #e5f4ec;
  --warn: #9a6200;
  --warn-soft: #fff4dc;

  --bubble-in: #ffffff;
  --bubble-out: #2f5bea;
  --bubble-out-text: #ffffff;

  --shadow-sm: 0 1px 2px rgb(16 24 40 / 0.06);
  --shadow-md: 0 6px 20px rgb(16 24 40 / 0.12);
  --focus: 0 0 0 3px rgb(47 91 234 / 0.35);

  --topbar-h: 52px;
  --inbox-w: 340px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f1115;
    --surface: #171a20;
    --surface-2: #1f232b;
    --border: #2a2f38;
    --text: #e8eaed;
    --text-muted: #9aa3ad;
    --accent: #6b8cff;
    --accent-text: #0b0d12;
    --accent-soft: #1e2847;
    --danger: #ff6b62;
    --danger-soft: #3a1c1a;
    --success: #4cc282;
    --success-soft: #16301f;
    --warn: #f0b545;
    --warn-soft: #362a12;
    --bubble-in: #1f232b;
    --bubble-out: #3a5bd9;
    --bubble-out-text: #ffffff;
    --shadow-sm: 0 1px 2px rgb(0 0 0 / 0.4);
    --shadow-md: 0 6px 20px rgb(0 0 0 / 0.5);
  }
}

/* ---------- base ---------- */
*,
*::before,
*::after {
  box-sizing: border-box;
}
html,
body,
#root {
  height: 100%;
}
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: var(--fs-md) / 1.45 var(--font-sans);
  -webkit-font-smoothing: antialiased;
}
h1,
h2,
p {
  margin: 0;
}
a {
  color: var(--accent);
}
:focus-visible {
  outline: none;
  box-shadow: var(--focus);
  border-radius: var(--radius-sm);
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
.center-fill {
  display: grid;
  place-items: center;
  height: 100%;
  padding: var(--space-5);
}
.center-pad {
  display: flex;
  justify-content: center;
  padding: var(--space-3);
}

/* ---------- primitives ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text);
  font: inherit;
  font-weight: 500;
  cursor: pointer;
  text-decoration: none;
  white-space: nowrap;
  transition: background 0.15s, border-color 0.15s;
}
.btn:hover:not(:disabled) {
  background: var(--surface-2);
}
.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}
.btn--sm {
  padding: 4px 10px;
  font-size: var(--fs-sm);
}
.btn--md {
  padding: 8px 16px;
}
.btn--primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-text);
}
.btn--primary:hover:not(:disabled) {
  background: var(--accent);
  filter: brightness(1.08);
}
.btn--ghost {
  background: transparent;
  border-color: transparent;
}
.btn--danger {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}
.linkbtn {
  border: 0;
  background: none;
  padding: 0;
  color: inherit;
  font: inherit;
  text-decoration: underline;
  cursor: pointer;
}

.spinner {
  display: inline-block;
  border: 2px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .spinner {
    animation-duration: 2.4s;
  }
}

.empty {
  text-align: center;
  color: var(--text-muted);
  padding: var(--space-5);
}
.empty__title {
  font-size: var(--fs-lg);
  color: var(--text);
}
.empty__body {
  margin-top: var(--space-3);
}

.pill {
  display: inline-block;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: var(--fs-xs);
  background: var(--surface-2);
  color: var(--text);
}
.pill--muted {
  color: var(--text-muted);
}
.pill--accent {
  background: var(--accent-soft);
  color: var(--accent);
}

.status {
  font-size: var(--fs-xs);
  white-space: nowrap;
}
.status--failed {
  color: var(--danger);
  font-weight: 600;
}

.conn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--fs-sm);
  color: var(--text-muted);
}
.conn__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--warn);
}
.conn--open .conn__dot {
  background: var(--success);
}
.conn--offline .conn__dot,
.conn--stopped .conn__dot {
  background: var(--danger);
}

.banner {
  grid-area: banner;
  padding: var(--space-2) var(--space-4);
  font-size: var(--fs-sm);
}
.banner--warn {
  background: var(--warn-soft);
  color: var(--warn);
}

.toasts {
  position: fixed;
  right: var(--space-4);
  bottom: var(--space-4);
  display: grid;
  gap: var(--space-2);
  z-index: 50;
  max-width: min(420px, calc(100vw - 32px));
}
.toast {
  display: flex;
  align-items: start;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-md);
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-md);
}
.toast--error {
  border-color: var(--danger);
  background: var(--danger-soft);
}
.toast--success {
  border-color: var(--success);
  background: var(--success-soft);
}
.toast__close {
  margin-left: auto;
  border: 0;
  background: none;
  color: inherit;
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
}

/* ---------- login ---------- */
.login {
  display: grid;
  place-items: center;
  min-height: 100%;
  padding: var(--space-4);
}
.login__card {
  width: min(380px, 100%);
  padding: var(--space-6);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  text-align: center;
}
.login__title {
  font-size: var(--fs-xl);
  margin-top: var(--space-3);
}
.login__subtitle {
  color: var(--text-muted);
  margin: var(--space-2) 0 var(--space-5);
}
.login__button {
  width: 100%;
}
.brand {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-sm);
  background: var(--accent);
  color: var(--accent-text);
}
.brand--lg {
  width: 48px;
  height: 48px;
  font-size: 24px;
  border-radius: var(--radius-md);
}

/* ---------- shell ---------- */
.shell {
  display: grid;
  height: 100%;
  grid-template-columns: var(--inbox-w) 1fr;
  grid-template-rows: var(--topbar-h) auto 1fr;
  grid-template-areas:
    'top top'
    'banner banner'
    'inbox pane';
}
.topbar {
  grid-area: top;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: 0 var(--space-4);
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.topbar__left,
.topbar__right {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  min-width: 0;
}
.topbar__user {
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 180px;
}
.ws-name {
  color: var(--text-muted);
}
.ws-switch select {
  font: inherit;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
}

.inbox {
  grid-area: inbox;
  min-height: 0;
  background: var(--surface);
  border-right: 1px solid var(--border);
  overflow-y: auto;
}
.pane {
  grid-area: pane;
  min-height: 0;
  min-width: 0;
}

.tabs {
  position: sticky;
  top: 0;
  z-index: 1;
  display: flex;
  gap: var(--space-1);
  padding: var(--space-2);
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.tab {
  flex: 1;
  padding: 6px 0;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  font: inherit;
  cursor: pointer;
}
.tab--active {
  background: var(--accent-soft);
  color: var(--accent);
  font-weight: 600;
}

.convlist {
  list-style: none;
  margin: 0;
  padding: 0;
}
.convrow {
  display: grid;
  gap: 2px;
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--border);
  color: inherit;
  text-decoration: none;
}
.convrow:hover {
  background: var(--surface-2);
}
.convrow--active {
  background: var(--accent-soft);
}
.convrow__top {
  display: flex;
  justify-content: space-between;
  gap: var(--space-2);
}
.convrow__contact {
  font-weight: 600;
  font-family: var(--font-mono);
  font-size: var(--fs-sm);
}
.convrow__time {
  font-size: var(--fs-xs);
  color: var(--text-muted);
  white-space: nowrap;
}
.convrow__preview {
  color: var(--text-muted);
  font-size: var(--fs-sm);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.convrow__meta {
  display: flex;
  gap: var(--space-1);
  margin-top: 2px;
}

/* ---------- conversation ---------- */
.conversation {
  display: grid;
  grid-template-rows: auto 1fr auto;
  height: 100%;
  min-height: 0;
}
.convhead {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}
.convhead__back {
  display: none;
  text-decoration: none;
  font-size: 20px;
}
.convhead__who {
  min-width: 0;
  flex: 1;
}
.convhead__contact {
  font-size: var(--fs-lg);
  font-family: var(--font-mono);
}
.convhead__sub {
  color: var(--text-muted);
  font-size: var(--fs-sm);
}
.convhead__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  justify-content: flex-end;
}

.thread {
  overflow-y: auto;
  min-height: 0;
  padding: var(--space-4);
}
.thread__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: var(--space-2);
}
.msg {
  display: flex;
}
.msg--out {
  justify-content: flex-end;
}
.msg__bubble {
  max-width: min(560px, 80%);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
}
.msg--in .msg__bubble {
  background: var(--bubble-in);
  border: 1px solid var(--border);
  border-bottom-left-radius: 2px;
}
.msg--out .msg__bubble {
  background: var(--bubble-out);
  color: var(--bubble-out-text);
  border-bottom-right-radius: 2px;
}
.msg--pending .msg__bubble {
  opacity: 0.75;
}
.msg__text {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.msg__meta {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-2);
  margin-top: 2px;
  font-size: var(--fs-xs);
  opacity: 0.8;
}
.msg__failed {
  font-weight: 600;
}

.composer {
  display: flex;
  gap: var(--space-2);
  align-items: flex-end;
  padding: var(--space-3) var(--space-4);
  background: var(--surface);
  border-top: 1px solid var(--border);
}
.composer__input {
  flex: 1;
  resize: none;
  min-height: 44px;
  max-height: 160px;
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--bg);
  color: var(--text);
  font: inherit;
}
.composer__input:disabled {
  opacity: 0.6;
}

/* ---------- small screens: one column, list OR conversation ---------- */
@media (max-width: 760px) {
  .shell {
    grid-template-columns: 1fr;
    grid-template-areas:
      'top'
      'banner'
      'main';
  }
  .inbox,
  .pane {
    grid-area: main;
  }
  .shell[data-has-conversation='true'] .inbox {
    display: none;
  }
  .shell[data-has-conversation='false'] .pane {
    display: none;
  }
  .convhead__back {
    display: inline;
  }
  .topbar__user {
    display: none;
  }
}

