import type { ObjectId } from 'mongodb';

// Persistent document shapes. DB_SCHEMA.md explains every field and index.

export type ConversationState = 'open' | 'closed';
export type Direction = 'in' | 'out';
export type DeliveryStatus = 'queued' | 'sent' | 'delivered' | 'failed';

export interface LastMessagePreview {
  text: string;
  dir: Direction;
  at: Date;
}

export interface ConversationDoc {
  _id: ObjectId;
  workspace: string;
  contact: string;
  state: ConversationState;
  assignee: string | null;
  assignedAt: Date | null;
  lastActivityAt: Date;
  lastMessage: LastMessagePreview | null;
  createdAt: Date;
  updatedAt: Date;
}

export interface MessageDoc {
  _id: ObjectId;
  workspace: string;
  contact: string;
  dir: Direction;
  text: string;
  occurredAt: Date;
  createdAt: Date;
  /** in: Pigeon pmsg_ id (dedupe key); out: Pigeon pm_ id once accepted */
  providerMessageId: string | null;

  // inbound
  eventId?: string;

  // outbound
  clientRef?: string;
  authorSub?: string | null;
  status?: DeliveryStatus;
  statusRank?: number;
  statusAt?: Date;

  // outbox: present only while a send is still owed
  outboxDueAt?: Date;
  outboxOwner?: string | null;
  sendAttempts?: number;
  lastSendError?: string | null;
  acceptedAt?: Date;
}

export const EVENT_TYPES = [
  'message.inbound',
  'message.outbound',
  'message.status',
  'conversation.assigned',
  'conversation.state',
] as const;
export type EventType = (typeof EVENT_TYPES)[number];

export interface EventDoc {
  _id: ObjectId;
  workspace: string;
  seq: number;
  type: EventType;
  contact: string;
  data: Record<string, unknown>;
  dedupeKey: string;
  createdAt: Date;
}

export interface CounterDoc {
  _id: string;
  value: number;
}

import type { DeliveryStatus } from '../types/domain.js';

// Delivery status only moves forward. delivered and failed are both final.
export const STATUS_RANK: Readonly<Record<DeliveryStatus, number>> = Object.freeze({
  queued: 0,
  sent: 1,
  delivered: 2,
  failed: 2,
});

export const DELIVERY_STATUSES = Object.keys(STATUS_RANK) as DeliveryStatus[];

export const isDeliveryStatus = (s: unknown): s is DeliveryStatus =>
  typeof s === 'string' && Object.hasOwn(STATUS_RANK, s);

export const rankOf = (s: DeliveryStatus): number => STATUS_RANK[s];

/** True if moving from `from` to `to` is allowed (strictly forward). */
export const canTransition = (from: DeliveryStatus | null | undefined, to: DeliveryStatus): boolean =>
  from == null || STATUS_RANK[to] > STATUS_RANK[from];

import { ObjectId } from 'mongodb';
import { AppError } from './AppError.js';

// Keyset pagination cursor: (timestamp, _id) encoded as base64url JSON.
// Opaque to clients, stable under inserts (no skip/offset drift).

export interface Cursor {
  t: Date;
  id: ObjectId;
}

export function encodeCursor(t: Date, id: ObjectId): string {
  return Buffer.from(JSON.stringify({ t: t.getTime(), id: id.toHexString() })).toString('base64url');
}

/** Throws VALIDATION_FAILED for anything malformed, so a bad cursor is a 400, never a 500. */
export function decodeCursor(raw: string | undefined | null): Cursor | null {
  if (!raw) return null;
  try {
    const v = JSON.parse(Buffer.from(raw, 'base64url').toString('utf8')) as { t?: unknown; id?: unknown };
    if (typeof v.t !== 'number' || !Number.isFinite(v.t) || typeof v.id !== 'string' || !ObjectId.isValid(v.id)) throw new Error();
    return { t: new Date(v.t), id: new ObjectId(v.id) };
  } catch {
    throw new AppError('VALIDATION_FAILED', { errors: [{ path: 'cursor', message: 'Invalid cursor' }] });
  }
}

/** Mongo filter for "strictly before (t, id)" in a (field desc, _id desc) ordering. */
export const beforeFilter = (field: string, c: Cursor) => ({
  $or: [{ [field]: { $lt: c.t } }, { [field]: c.t, _id: { $lt: c.id } }],
});

import type { Collection } from 'mongodb';
import { getDb } from '../infra/mongo.js';
import type { ConversationDoc, CounterDoc, EventDoc, MessageDoc } from '../types/domain.js';

export const COLLECTIONS = {
  conversations: 'conversations',
  messages: 'messages',
  events: 'events',
  counters: 'counters',
} as const;

/** Typed collection handles. Only repositories import this file. */
export const col = {
  conversations: (): Collection<ConversationDoc> => getDb().collection<ConversationDoc>(COLLECTIONS.conversations),
  messages: (): Collection<MessageDoc> => getDb().collection<MessageDoc>(COLLECTIONS.messages),
  events: (): Collection<EventDoc> => getDb().collection<EventDoc>(COLLECTIONS.events),
  counters: (): Collection<CounterDoc> => getDb().collection<CounterDoc>(COLLECTIONS.counters),
};

import type { Db, IndexDescription } from 'mongodb';
import { logger } from '../infra/logger.js';
import { COLLECTIONS } from './collections.js';

const EVENT_TTL_SECONDS = 7 * 24 * 60 * 60;

/**
 * Every index, with the reason it exists in DB_SCHEMA.md. createIndexes is
 * idempotent and safe when several instances boot at once.
 */
export const INDEXES: Record<string, IndexDescription[]> = {
  [COLLECTIONS.conversations]: [
    { key: { workspace: 1, contact: 1 }, name: 'uniq_ws_contact', unique: true },
    { key: { workspace: 1, lastActivityAt: -1, _id: -1 }, name: 'inbox_all' },
    { key: { workspace: 1, state: 1, lastActivityAt: -1, _id: -1 }, name: 'inbox_state' },
    { key: { workspace: 1, assignee: 1, lastActivityAt: -1, _id: -1 }, name: 'inbox_assignee' },
  ],
  [COLLECTIONS.messages]: [
    {
      key: { workspace: 1, providerMessageId: 1 },
      name: 'uniq_inbound_provider_id',
      unique: true,
      partialFilterExpression: { dir: 'in' },
    },
    {
      key: { workspace: 1, clientRef: 1 },
      name: 'uniq_outbound_client_ref',
      unique: true,
      partialFilterExpression: { dir: 'out' },
    },
    { key: { workspace: 1, contact: 1, occurredAt: 1, _id: 1 }, name: 'thread' },
    { key: { outboxDueAt: 1 }, name: 'outbox_due', partialFilterExpression: { outboxDueAt: { $exists: true } } },
  ],
  [COLLECTIONS.events]: [
    { key: { workspace: 1, seq: 1 }, name: 'uniq_ws_seq', unique: true },
    { key: { workspace: 1, dedupeKey: 1 }, name: 'uniq_ws_dedupe', unique: true },
    { key: { createdAt: 1 }, name: 'ttl_created', expireAfterSeconds: EVENT_TTL_SECONDS },
  ],
  [COLLECTIONS.counters]: [],
};

export async function ensureIndexes(db: Db): Promise<void> {
  for (const [collection, specs] of Object.entries(INDEXES)) {
    if (specs.length) await db.collection(collection).createIndexes(specs);
  }
  logger.info('indexes ensured', { collections: Object.keys(INDEXES).length });
}

