import { ObjectId } from 'mongodb';
import { isDuplicateKeyError } from '../infra/mongo.js';
import type { EventDoc, EventType } from '../types/domain.js';
import { col } from './collections.js';
import { counterRepo } from './counter.repo.js';

export interface AppendInput {
  workspace: string;
  type: EventType;
  contact: string;
  data: Record<string, unknown>;
  /** Same fact → same key; a retried webhook cannot emit a second frame. */
  dedupeKey: string;
}

export const eventRepo = {
  /**
   * Allocate a seq and store the event. Returns null if this dedupeKey was
   * already recorded (the allocated seq is then simply unused: gaps are fine).
   */
  async append(input: AppendInput, now = new Date()): Promise<EventDoc | null> {
    const seq = await counterRepo.nextSeq(input.workspace);
    const doc: EventDoc = { _id: new ObjectId(), seq, createdAt: now, ...input };
    try {
      await col.events().insertOne(doc);
      return doc;
    } catch (err) {
      if (isDuplicateKeyError(err)) return null;
      throw err;
    }
  },

  /** Replay for GET /ws?after=N, in seq order. */
  async listAfter(workspace: string, after: number, limit = 500): Promise<EventDoc[]> {
    return col
      .events()
      .find({ workspace, seq: { $gt: after } })
      .sort({ seq: 1 })
      .limit(limit)
      .toArray();
  },

  /** Gap fill: events in (after, upTo], in seq order. */
  async listRange(workspace: string, after: number, upTo: number): Promise<EventDoc[]> {
    return col
      .events()
      .find({ workspace, seq: { $gt: after, $lte: upTo } })
      .sort({ seq: 1 })
      .toArray();
  },

  async deleteAll(): Promise<void> {
    await col.events().deleteMany({});
  },
};

