import type { CookieOptions } from 'express';
import { env } from '../config/env.js';

/**
 * Secure follows the public URL scheme, NOT NODE_ENV: the check runs with
 * NODE_ENV=production over plain http, where a Secure cookie would be dropped.
 */
const secure = env.oidc.redirectUri.startsWith('https:');

export const sessionCookieOptions = (maxAgeSeconds: number): CookieOptions => ({
  httpOnly: true,
  sameSite: 'lax', // sent on the top-level redirect back from the IdP, not on cross-site POSTs
  secure,
  path: '/',
  maxAge: maxAgeSeconds * 1000,
});

export const loginCookieOptions = (maxAgeSeconds: number): CookieOptions => ({
  httpOnly: true,
  sameSite: 'lax',
  secure,
  path: '/auth',
  maxAge: maxAgeSeconds * 1000,
});

/** Minimal Cookie header parser for places without Express (WebSocket upgrade). */
export function parseCookieHeader(header: string | undefined): Record<string, string> {
  const out: Record<string, string> = {};
  if (!header) return out;
  for (const part of header.split(';')) {
    const i = part.indexOf('=');
    if (i < 0) continue;
    const k = part.slice(0, i).trim();
    const v = part.slice(i + 1).trim();
    if (!k || k in out) continue;
    try {
      out[k] = decodeURIComponent(v);
    } catch {
      out[k] = v;
    }
  }
  return out;
}

import { z } from 'zod';
import { ROLES } from '../constants/roles.js';

/** Only same-site relative paths: "/w/ws_acme". Blocks open redirects ("//evil.com", "https://…"). */
export const SafeReturnTo = z
  .string()
  .max(512)
  .refine((v) => v.startsWith('/') && !v.startsWith('//') && !v.includes('\\'), 'Must be a relative path');

export const LoginQuery = z.object({
  returnTo: SafeReturnTo.optional().catch(undefined),
});

export const CallbackQuery = z.object({
  code: z.string().min(1).max(2048).optional(),
  state: z.string().min(1).max(256).optional(),
  error: z.string().max(256).optional(),
  error_description: z.string().max(1024).optional(),
});

/** OIDC discovery document: only the fields we use. */
export const DiscoveryDoc = z.object({
  issuer: z.string().url(),
  authorization_endpoint: z.string().url(),
  token_endpoint: z.string().url(),
  jwks_uri: z.string().url(),
});

export const TokenResponse = z.object({
  id_token: z.string().min(1),
  access_token: z.string().optional(),
  token_type: z.string().optional(),
});

/** Custom claim: [{ id, role }]. Unknown roles are dropped, not trusted. */
export const WorkspacesClaim = z
  .array(z.object({ id: z.string().min(1).max(128), role: z.string() }))
  .transform((list) =>
    list
      .filter((w): w is { id: string; role: (typeof ROLES)[number] } => (ROLES as readonly string[]).includes(w.role))
      .map(({ id, role }) => ({ id, role })),
  );

export const IdTokenClaims = z.object({
  sub: z.string().min(1),
  nonce: z.string().optional(),
  name: z.string().optional(),
  email: z.string().optional(),
  workspaces: WorkspacesClaim.default([]),
});

/** Stored in Redis under sb:oidc:<state> between /auth/login and /auth/callback. */
export const PendingLogin = z.object({
  verifier: z.string(),
  nonce: z.string(),
  returnTo: z.string().optional(),
});
export type PendingLogin = z.infer<typeof PendingLogin>;

import { z } from 'zod';
import { SESSION } from '../config/constants.js';
import { ROLES } from '../constants/roles.js';
import { getRedis, rkey } from '../infra/redis.js';
import type { SessionUser } from '../types/express.js';
import { randomToken, sha256 } from '../utils/crypto.js';

// Server-side sessions in Redis, shared by every instance. The cookie holds a
// random id; Redis stores only its SHA-256, so a Redis dump does not contain
