import { createRemoteJWKSet, jwtVerify, type JWTVerifyGetKey } from 'jose';
import { z } from 'zod';
import { OIDC, SESSION } from '../config/constants.js';
import { env } from '../config/env.js';
import { getRedis, rkey } from '../infra/redis.js';
import { logger } from '../infra/logger.js';
import type { SessionUser } from '../types/express.js';
import { AppError } from '../utils/AppError.js';
import { randomToken, sha256 } from '../utils/crypto.js';
import { DiscoveryDoc, IdTokenClaims, PendingLogin, TokenResponse } from '../validators/auth.schema.js';

// OpenID Connect, authorization code + PKCE (S256), done on the server.
// The browser never sees tokens; it only gets an httpOnly session cookie.

type Discovery = z.infer<typeof DiscoveryDoc>;

let discoveryPromise: Promise<{ doc: Discovery; jwks: JWTVerifyGetKey }> | null = null;

/** Fetched once and cached; a failure is not cached so the next login retries. */
function discovery() {
  discoveryPromise ??= (async () => {
    const url = `${env.oidc.issuer.replace(/\/$/, '')}/.well-known/openid-configuration`;
    const res = await fetch(url, { signal: AbortSignal.timeout(OIDC.httpTimeoutMs) });
    if (!res.ok) throw new Error(`discovery answered ${res.status}`);
    const doc = DiscoveryDoc.parse(await res.json());
    return { doc, jwks: createRemoteJWKSet(new URL(doc.jwks_uri)) };
  })().catch((err) => {
    discoveryPromise = null;
    logger.warn('oidc discovery failed', { err });
    throw new AppError('IDP_UNAVAILABLE', { cause: err });
  });
  return discoveryPromise;
}

const pendingKey = (state: string) => rkey('oidc', state);

export const authService = {
  /**
   * Step 1: build the IdP redirect. PKCE verifier + nonce are stored in Redis
   * (not memory) because the callback may land on another instance.
   */
  async startLogin(returnTo?: string): Promise<{ url: string; state: string }> {
    const { doc } = await discovery();
    const state = randomToken(24);
    const nonce = randomToken(24);
    const verifier = randomToken(48); // 64 chars, within RFC 7636's 43–128
    const challenge = sha256(verifier).toString('base64url');

    const pending: PendingLogin = { verifier, nonce, returnTo };
    await getRedis().set(pendingKey(state), JSON.stringify(pending), 'EX', SESSION.loginStateTtlSeconds);

    const url = new URL(doc.authorization_endpoint);
    url.search = new URLSearchParams({
      response_type: 'code',
      client_id: env.oidc.clientId,
      redirect_uri: env.oidc.redirectUri,
      scope: OIDC.scope,
      state,
      nonce,
      code_challenge: challenge,
      code_challenge_method: 'S256',
    }).toString();
    return { url: url.toString(), state };
  },

  /** Step 2: single-use state → code exchange → verify id_token → session user. */
  async finishLogin(code: string, state: string): Promise<{ user: SessionUser; returnTo?: string }> {
    const raw = await getRedis().getdel(pendingKey(state)); // single use: a replayed callback fails
    if (!raw) throw new AppError('LOGIN_STATE_INVALID');
    const pending = PendingLogin.parse(JSON.parse(raw));
    const { doc, jwks } = await discovery();

    let tokenRes: Response;
    try {
      tokenRes = await fetch(doc.token_endpoint, {
        method: 'POST',
        headers: {
          'content-type': 'application/x-www-form-urlencoded',
          accept: 'application/json',
          authorization: 'Basic ' + Buffer.from(`${encodeURIComponent(env.oidc.clientId)}:${encodeURIComponent(env.oidc.clientSecret)}`).toString('base64'),
        },
        body: new URLSearchParams({
          grant_type: 'authorization_code',
          code,
          redirect_uri: env.oidc.redirectUri,
          code_verifier: pending.verifier,
        }),
        signal: AbortSignal.timeout(OIDC.httpTimeoutMs),
      });
    } catch (err) {
      throw new AppError('IDP_UNAVAILABLE', { cause: err });
    }
    if (!tokenRes.ok) {
      logger.warn('oidc token exchange rejected', { status: tokenRes.status, body: (await tokenRes.text()).slice(0, 200) });
      throw new AppError('LOGIN_FAILED');
    }

    const tokens = TokenResponse.parse(await tokenRes.json());
    let claims: z.infer<typeof IdTokenClaims>;
    try {
      const { payload } = await jwtVerify(tokens.id_token, jwks, {
        issuer: doc.issuer,
        audience: env.oidc.clientId,
        algorithms: ['RS256'],
        clockTolerance: OIDC.clockToleranceSeconds,
      });
      claims = IdTokenClaims.parse(payload);
    } catch (err) {
      logger.warn('id_token rejected', { err });
      throw new AppError('LOGIN_FAILED', { cause: err });
    }
    if (claims.nonce !== pending.nonce) throw new AppError('LOGIN_FAILED', { message: 'Nonce mismatch.' });

    return {
      user: { sub: claims.sub, name: claims.name, email: claims.email, workspaces: claims.workspaces },
      returnTo: pending.returnTo,
    };
  },
};

import type { RequestHandler } from 'express';
import { SESSION } from '../config/constants.js';
import { sessionService } from '../services/session.service.js';
import { AppError } from '../utils/AppError.js';
import { asyncHandler } from '../utils/asyncHandler.js';

/** 401 without a valid session cookie; otherwise sets req.user. */
export const requireSession: RequestHandler = asyncHandler(async (req, _res, next) => {
  const user = await sessionService.get(req.cookies?.[SESSION.cookieName]);
  if (!user) throw new AppError('UNAUTHENTICATED');
  req.user = user;
  next();
});

import type { RequestHandler } from 'express';
import { can, type Permission } from '../constants/roles.js';
import type { SessionUser, WorkspaceMembership } from '../types/express.js';
import { AppError } from '../utils/AppError.js';

/** Membership lookup shared with the WebSocket gateway. */
export const membershipOf = (user: SessionUser | undefined, workspace: unknown): WorkspaceMembership | null =>
  typeof workspace === 'string' && user ? (user.workspaces.find((w) => w.id === workspace) ?? null) : null;

/**
 * Tenant gate. Reads ?workspace= (or :workspace), requires the session user to
 * be a member, and sets req.workspace. Must run after requireSession.
 * 401 without a session, 403 for a signed-in non-member (contract E).
 */
export const requireMember: RequestHandler = (req, _res, next) => {
  if (!req.user) return next(new AppError('UNAUTHENTICATED'));
  const ws = req.params.workspace ?? req.query.workspace;
  if (typeof ws !== 'string' || !ws) {
    return next(new AppError('VALIDATION_FAILED', { errors: [{ path: 'workspace', message: 'Required' }] }));
  }
  const membership = membershipOf(req.user, ws);
  if (!membership) return next(new AppError('FORBIDDEN_WORKSPACE'));
  req.workspace = membership;
  next();
};

/** Role gate by permission name, e.g. requirePermission('conversation.reassign'). Run after requireMember. */
export const requirePermission =
  (permission: Permission): RequestHandler =>
  (req, _res, next) => {
    if (!req.workspace || !can(req.workspace.role, permission)) return next(new AppError('FORBIDDEN_ROLE'));
    next();
  };

import type { Request, Response } from 'express';
import type { z } from 'zod';
import { SESSION } from '../config/constants.js';
import { env } from '../config/env.js';
import { logger } from '../infra/logger.js';
import { authService } from '../services/auth.service.js';
import { sessionService } from '../services/session.service.js';
import { isAppError } from '../utils/AppError.js';
import { loginCookieOptions, sessionCookieOptions } from '../utils/cookies.js';
import { safeEqual } from '../utils/crypto.js';
import { respond } from '../utils/respond.js';
import type { CallbackQuery, LoginQuery } from '../validators/auth.schema.js';

/** Where the browser lands after login/logout: the React app (WEB_ORIGIN). */
const appUrl = (path = '/') => new URL(path, env.webOrigin).toString();

export const authController = {
  /** GET /auth/login → 302 to the IdP (contract E). */
  async login(req: Request, res: Response) {
    const { returnTo } = req.query as z.infer<typeof LoginQuery>;
    const { url, state } = await authService.startLogin(returnTo);
    res.cookie(SESSION.loginCookieName, state, loginCookieOptions(SESSION.loginStateTtlSeconds));
    res.redirect(302, url);
  },

  /**
   * GET /auth/callback → verify, create session, set cookie, 302 to the app.
   * Failures send the browser to the login page with a reason, not a JSON page.
   */
  async callback(req: Request, res: Response) {
    const q = req.query as z.infer<typeof CallbackQuery>;
    res.clearCookie(SESSION.loginCookieName, loginCookieOptions(0));

    const fail = (code: string) => res.redirect(302, appUrl(`/login?error=${encodeURIComponent(code)}`));

    if (q.error || !q.code || !q.state) {
      logger.warn('oidc callback without code', { error: q.error, desc: q.error_description });
      return fail('LOGIN_DENIED');
    }
    // Login CSRF: the state must belong to the browser that started this login.
    const bound = req.cookies?.[SESSION.loginCookieName];
    if (typeof bound !== 'string' || !safeEqual(bound, q.state)) return fail('LOGIN_STATE_INVALID');

    try {
      const { user, returnTo } = await authService.finishLogin(q.code, q.state);
      // Rotate: drop any previous session in this browser (session fixation).
      await sessionService.destroy(req.cookies?.[SESSION.cookieName]);
      const sid = await sessionService.create(user);
      res.cookie(SESSION.cookieName, sid, sessionCookieOptions(SESSION.ttlSeconds));
      logger.info('login', { sub: user.sub, workspaces: user.workspaces.map((w) => w.id) });
      return res.redirect(302, appUrl(returnTo ?? '/'));
    } catch (err) {
      if (isAppError(err)) return fail(err.code);
      throw err;
    }
  },

  /** POST /auth/logout → destroy the server session and clear the cookie. */
  async logout(req: Request, res: Response) {
    await sessionService.destroy(req.cookies?.[SESSION.cookieName]);
    res.clearCookie(SESSION.cookieName, sessionCookieOptions(0));
    return respond.ok(res, 'LOGGED_OUT', null);
  },
};

import type { Request, Response } from 'express';
