// Mirrors harness/check.js signIn() plus negative cases.
const APP = 'http://127.0.0.1:4000';
const results = [];
const check = (name, ok, detail = '') => results.push(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  — ' + detail : ''}`);

async function signIn(sub) {
  const jar = {};
  const keep = (res) => {
    for (const c of res.headers.getSetCookie()) {
      const [pair] = c.split(';');
      const i = pair.indexOf('=');
      jar[pair.slice(0, i).trim()] = pair.slice(i + 1);
    }
  };
  const cookie = () => Object.entries(jar).map(([k, v]) => k + '=' + v).join('; ');
  const get = (url) => fetch(url, { redirect: 'manual', headers: { cookie: cookie() } });
  const start = await get(APP + '/auth/login?returnTo=/w/ws_acme');
  keep(start);
  const toIdp = start.headers.get('location');
  const picked = await fetch(toIdp + '&login=' + sub, { redirect: 'manual' });
  const back = picked.headers.get('location');
  const u = new URL(back);
  const cb = await get(APP + u.pathname + u.search);
  keep(cb);
  return { jar, cookie: cookie(), startStatus: start.status, toIdp, cbStatus: cb.status, cbLocation: cb.headers.get('location'), callbackUrl: back, setCookie: cb.headers.getSetCookie() };
}

const ben = await signIn('u_ben');
check('login redirects to IdP with PKCE S256', ben.startStatus === 302 && /code_challenge_method=S256/.test(ben.toIdp));
check('callback 302 to WEB_ORIGIN + returnTo', ben.cbStatus === 302 && ben.cbLocation === 'http://localhost:5173/w/ws_acme', ben.cbLocation);
check('session cookie httpOnly, SameSite=Lax, not Secure on http', ben.setCookie.some((c) => /^sb_sid=/.test(c) && /HttpOnly/i.test(c) && /SameSite=Lax/i.test(c) && !/Secure/i.test(c)));

const me = await fetch(APP + '/api/me', { headers: { cookie: ben.cookie } });
const meBody = await me.json();
check('GET /api/me with session = check shape', me.status === 200 && meBody.sub === 'u_ben' && meBody.workspaces.length === 1 && meBody.workspaces[0].id === 'ws_acme' && meBody.workspaces[0].role === 'agent', JSON.stringify(meBody));

const anon = await fetch(APP + '/api/me');
check('GET /api/me without session = 401 envelope', anon.status === 401 && (await anon.json()).code === 'UNAUTHENTICATED');

const forged = await fetch(APP + '/api/me', { headers: { cookie: 'sb_sid=forged-value' } });
check('forged session id = 401', forged.status === 401);

// replaying the same callback URL (code + state already used)
const replay = await fetch(APP + new URL(ben.callbackUrl).pathname + new URL(ben.callbackUrl).search, { redirect: 'manual', headers: { cookie: 'sb_login=' + new URL(ben.callbackUrl).searchParams.get('state') } });
check('replayed callback is rejected', replay.status === 302 && /error=LOGIN_STATE_INVALID/.test(replay.headers.get('location')), replay.headers.get('location'));

// login CSRF: callback without the browser-bound login cookie
const start2 = await fetch(APP + '/auth/login', { redirect: 'manual' });
const picked2 = await fetch(start2.headers.get('location') + '&login=u_ben', { redirect: 'manual' });
const u2 = new URL(picked2.headers.get('location'));
const csrf = await fetch(APP + u2.pathname + u2.search, { redirect: 'manual' });
check('callback from another browser (no sb_login cookie) is rejected', /error=LOGIN_STATE_INVALID/.test(csrf.headers.get('location')));

const open = await fetch(APP + '/auth/login?returnTo=//evil.example', { redirect: 'manual' });
check('open redirect returnTo is dropped (login still works)', open.status === 302);

const eli = await signIn('u_eli');
const eliMe = await (await fetch(APP + '/api/me', { headers: { cookie: eli.cookie } })).json();
check('multi-workspace user gets both memberships', eliMe.workspaces.length === 2, JSON.stringify(eliMe.workspaces));

const out = await fetch(APP + '/auth/logout', { method: 'POST', headers: { cookie: ben.cookie } });
const afterOut = await fetch(APP + '/api/me', { headers: { cookie: ben.cookie } });
check('logout destroys the server session', out.status === 200 && afterOut.status === 401);

console.log(results.join('\n'));
process.exit(results.some((r) => r.startsWith('FAIL')) ? 1 : 0);

