// Mirrors harness/check.js signIn() plus negative cases.
const APP = 'http://127.0.0.1:4000';
const results = [];
const check = (name, ok, detail = '') => results.push(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  — ' + detail : ''}`);

async function signIn(sub) {
  const jar = {};
  const keep = (res) => {
    for (const c of res.headers.getSetCookie()) {
      const [pair] = c.split(';');
      const i = pair.indexOf('=');
      jar[pair.slice(0, i).trim()] = pair.slice(i + 1);
    }
  };
  const cookie = () => Object.entries(jar).map(([k, v]) => k + '=' + v).join('; ');
  const get = (url) => fetch(url, { redirect: 'manual', headers: { cookie: cookie() } });
  const start = await get(APP + '/auth/login?returnTo=/w/ws_acme');
  keep(start);
  const toIdp = start.headers.get('location');
  const picked = await fetch(toIdp + '&login=' + sub, { redirect: 'manual' });
  const back = picked.headers.get('location');
  const u = new URL(back);
  const cb = await get(APP + u.pathname + u.search);
  keep(cb);
  return { jar, cookie: cookie(), startStatus: start.status, toIdp, cbStatus: cb.status, cbLocation: cb.headers.get('location'), callbackUrl: back, setCookie: cb.headers.getSetCookie() };
}

const ben = await signIn('u_ben');
check('login redirects to IdP with PKCE S256', ben.startStatus === 302 && /code_challenge_method=S256/.test(ben.toIdp));
check('callback 302 to WEB_ORIGIN + returnTo', ben.cbStatus === 302 && ben.cbLocation === 'http://localhost:5173/w/ws_acme', ben.cbLocation);
check('session cookie httpOnly, SameSite=Lax, not Secure on http', ben.setCookie.some((c) => /^sb_sid=/.test(c) && /HttpOnly/i.test(c) && /SameSite=Lax/i.test(c) && !/Secure/i.test(c)));

const me = await fetch(APP + '/api/me', { headers: { cookie: ben.cookie } });
const meBody = await me.json();
