const forged = await fetch(APP + '/api/me', { headers: { cookie: 'sb_sid=forged-value' } });
check('forged session id = 401', forged.status === 401);

// replaying the same callback URL (code + state already used)
const replay = await fetch(APP + new URL(ben.callbackUrl).pathname + new URL(ben.callbackUrl).search, { redirect: 'manual', headers: { cookie: 'sb_login=' + new URL(ben.callbackUrl).searchParams.get('state') } });
check('replayed callback is rejected', replay.status === 302 && /error=LOGIN_STATE_INVALID/.test(replay.headers.get('location')), replay.headers.get('location'));

// login CSRF: callback without the browser-bound login cookie
const start2 = await fetch(APP + '/auth/login', { redirect: 'manual' });
