check('callback from another browser (no sb_login cookie) is rejected', /error=LOGIN_STATE_INVALID/.test(csrf.headers.get('location')));

const open = await fetch(APP + '/auth/login?returnTo=//evil.example', { redirect: 'manual' });
check('open redirect returnTo is dropped (login still works)', open.status === 302);

const eli = await signIn('u_eli');
const eliMe = await (await fetch(APP + '/api/me', { headers: { cookie: eli.cookie } })).json();
check('multi-workspace user gets both memberships', eliMe.workspaces.length === 2, JSON.stringify(eliMe.workspaces));

