// Browser-like login through the Vite dev server (:5173), as a real user would.
const WEB = 'http://localhost:5173';
const results = [];
const check = (name, ok, detail = '') => results.push(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? '  — ' + detail : ''}`);
const jar = {};
const keep = (res) => {
  for (const c of res.headers.getSetCookie()) {
    const [pair] = c.split(';');
    const i = pair.indexOf('=');
    jar[pair.slice(0, i).trim()] = pair.slice(i + 1);
  }
};
const cookie = () => Object.entries(jar).filter(([, v]) => v).map(([k, v]) => k + '=' + v).join('; ');
const get = (url, init = {}) => fetch(url, { redirect: 'manual', ...init, headers: { cookie: cookie(), ...(init.headers || {}) } });

const html = await get(WEB + '/w/ws_acme/c/%2B14155550101?filter=mine');
check('SPA deep link serves index.html', html.status === 200 && (await html.text()).includes('id="root"'));

const meAnon = await get(WEB + '/api/me');
check('/api/me via proxy without session = 401', meAnon.status === 401);

// 1. click "Continue with company sign-in"
const login = await get(WEB + '/auth/login?returnTo=' + encodeURIComponent('/w/ws_acme?filter=mine'));
keep(login);
check('/auth/login via proxy redirects to IdP', login.status === 302 && login.headers.get('location').startsWith('http://localhost:4020/authorize'));
// 2. pick a user on the IdP page
const idp = await fetch(login.headers.get('location') + '&login=u_eli', { redirect: 'manual' });
const callback = idp.headers.get('location');
check('IdP returns to OIDC_REDIRECT_URI', callback.startsWith('http://localhost:4000/auth/callback'), callback.split('?')[0]);
// 3. browser follows to the callback (cookie jar is per host, port-agnostic)
const cb = await get(callback);
keep(cb);
check('callback lands back on the web app with returnTo', cb.headers.get('location') === WEB + '/w/ws_acme?filter=mine', cb.headers.get('location'));
// 4. the SPA calls /api/me through the proxy with the cookie
const me = await get(WEB + '/api/me');
const body = await me.json();
check('/api/me via proxy with session', me.status === 200 && body.sub === 'u_eli' && body.workspaces.length === 2, JSON.stringify(body.workspaces));
// 5. sign out
const out = await get(WEB + '/auth/logout', { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{}' });
keep(out);
const after = await get(WEB + '/api/me');
check('logout via proxy clears session', out.status === 200 && after.status === 401);

console.log(results.join('\n'));
process.exit(results.some((r) => r.startsWith('FAIL')) ? 1 : 0);

