import { z } from 'zod';
import { PAGINATION } from '../config/constants.js';

export const ListConversationsQuery = z.object({
  workspace: z.string().min(1).max(128),
  filter: z.enum(['open', 'closed', 'mine', 'all']).default('open'),
  cursor: z.string().max(512).optional(),
  limit: z.coerce.number().int().min(1).max(PAGINATION.maxLimit).default(PAGINATION.defaultLimit),
});
export type ListConversationsQuery = z.infer<typeof ListConversationsQuery>;

import { conversationRepo, type InboxFilter } from '../repositories/conversation.repo.js';
import type { ConversationDoc } from '../types/domain.js';
import { decodeCursor } from '../utils/cursor.js';

/** API shape of a conversation (what the React app renders). */
export const toConversationDto = (c: ConversationDoc) => ({
  contact: c.contact,
  state: c.state,
  assignee: c.assignee,
  lastActivityAt: c.lastActivityAt.toISOString(),
  lastMessage: c.lastMessage ? { text: c.lastMessage.text, dir: c.lastMessage.dir, at: c.lastMessage.at.toISOString() } : null,
});

export const conversationService = {
  /** Inbox page. `workspace` must already be membership-checked by the caller (requireMember). */
  async list(workspace: string, me: string, q: { filter: InboxFilter; cursor?: string; limit: number }) {
    const page = await conversationRepo.list(workspace, {
      filter: q.filter,
      me,
      cursor: decodeCursor(q.cursor),
      limit: q.limit,
    });
    return { items: page.items.map(toConversationDto), nextCursor: page.nextCursor };
  },
};

import type { Request, Response } from 'express';
import { conversationService } from '../services/conversation.service.js';
import { respond } from '../utils/respond.js';
import type { ListConversationsQuery } from '../validators/conversation.schema.js';

export const conversationController = {
  /** GET /api/conversations?workspace=&filter=&cursor=&limit= (contract E: 200 member / 403 / 401). */
  async list(req: Request, res: Response) {
    const q = req.query as unknown as ListConversationsQuery;
    const page = await conversationService.list(req.workspace!.id, req.user!.sub, q);
    return respond.ok(res, 'CONVERSATIONS_LISTED', { items: page.items }, { meta: { nextCursor: page.nextCursor } });
  },
};

import { Router } from 'express';
import { conversationController } from '../controllers/conversation.controller.js';
import { requireWorkspaceMember } from '../middleware/requireMember.js';
import { requireSession } from '../middleware/requireSession.js';
import { validate } from '../middleware/validate.js';
import { asyncHandler } from '../utils/asyncHandler.js';
import { ListConversationsQuery } from '../validators/conversation.schema.js';

export const conversationRoutes = Router();

// Order matters: 401 (no session) before 403 (not a member) before 400 (bad query).
conversationRoutes.get(
  '/api/conversations',
  requireSession,
  requireWorkspaceMember,
  validate({ query: ListConversationsQuery }),
  asyncHandler(conversationController.list),
