import { getRedis, rkey } from '../infra/redis.js';
import { conversationRepo } from '../repositories/conversation.repo.js';
import { counterRepo } from '../repositories/counter.repo.js';
import { eventRepo } from '../repositories/event.repo.js';
import { messageRepo } from '../repositories/message.repo.js';

/** Redis key families that are application data. Sessions and pending logins are kept. */
const APP_KEY_PATTERNS = [rkey('rl', '*'), rkey('cool', '*')];

export const resetService = {
  /** Contract D: delete all application data in MongoDB and Redis; login sessions may stay. */
  async resetAll(): Promise<void> {
    await Promise.all([conversationRepo.deleteAll(), messageRepo.deleteAll(), eventRepo.deleteAll(), counterRepo.deleteAll()]);
    const redis = getRedis();
    for (const match of APP_KEY_PATTERNS) {
      let cursor = '0';
      do {
        const [next, keys] = await redis.scan(cursor, 'MATCH', match, 'COUNT', 500);
        if (keys.length) await redis.del(...keys);
        cursor = next;
      } while (cursor !== '0');
    }
  },
};

