import { conversationRepo } from '../repositories/conversation.repo.js';
import { counterRepo } from '../repositories/counter.repo.js';
import { eventRepo } from '../repositories/event.repo.js';
import { messageRepo } from '../repositories/message.repo.js';

/** Redis key families that are application data. Sessions and pending logins are kept. */
const APP_KEY_PATTERNS = [rkey('rl', '*'), rkey('cool', '*')];

export const resetService = {
  /** Contract D: delete all application data in MongoDB and Redis; login sessions may stay. */
  async resetAll(): Promise<void> {
    await Promise.all([conversationRepo.deleteAll(), messageRepo.deleteAll(), eventRepo.deleteAll(), counterRepo.deleteAll()]);
    const redis = getRedis();
    for (const match of APP_KEY_PATTERNS) {
      let cursor = '0';
      do {
        const [next, keys] = await redis.scan(cursor, 'MATCH', match, 'COUNT', 500);
        if (keys.length) await redis.del(...keys);
        cursor = next;
      } while (cursor !== '0');
    }
  },
};

import type { Request, Response } from 'express';
import { resetService } from '../services/reset.service.js';
import { respond } from '../utils/respond.js';

// Contract D. Token-protected (requireGraderToken), never session-protected.
// snapshot / reply / claim are added in the core phase.
export const graderController = {
  async reset(_req: Request, res: Response) {
    await resetService.resetAll();
    return respond.raw(res, 200, { ok: true });
  },
};

import { Router } from 'express';
import { graderController } from '../controllers/grader.controller.js';
import { requireGraderToken } from '../middleware/requireGraderToken.js';
import { asyncHandler } from '../utils/asyncHandler.js';

export const graderRoutes = Router();

graderRoutes.use('/__grader', requireGraderToken);
graderRoutes.post('/__grader/reset', asyncHandler(graderController.reset));

// Manual attack tests against one instance on APP (callback rewritten onto it, as the check does).
const APP = process.argv[2] || 'http://127.0.0.1:4103';
const out = [];
const check = (n, ok, d = '') => out.push(`${ok ? 'PASS' : 'FAIL'}  ${n}${d ? '  — ' + d : ''}`);

function browser() {
  const jar = {};
  const keep = (res) => {
    for (const c of res.headers.getSetCookie()) {
      const [pair] = c.split(';');
      const i = pair.indexOf('=');
      jar[pair.slice(0, i).trim()] = pair.slice(i + 1);
    }
  };
  const cookie = () => Object.entries(jar).filter(([, v]) => v).map(([k, v]) => `${k}=${v}`).join('; ');
  const get = (path, init = {}) => fetch(APP + path, { redirect: 'manual', ...init, headers: { cookie: cookie(), ...(init.headers || {}) } }).then((r) => (keep(r), r));
  return { jar, cookie, get, keep };
}

async function startLogin(b, sub) {
  const s = await b.get('/auth/login');
  const idp = await fetch(s.headers.get('location') + '&login=' + sub, { redirect: 'manual' });
  const cb = new URL(idp.headers.get('location'));
  return cb.pathname + cb.search; // /auth/callback?code=..&state=..
}

// 1. normal login (u_ben, agent in ws_acme only)
const ben = browser();
const cbPath = await startLogin(ben, 'u_ben');
const ok = await ben.get(cbPath);
check('valid callback → 302 + session cookie', ok.status === 302 && 'sb_sid' in ben.jar);

// 2. reused callback URL (same browser, same code+state)
const reuse = browser();
Object.assign(reuse.jar, { sb_login: new URL(APP + cbPath).searchParams.get('state') });
const r = await reuse.get(cbPath, { headers: { accept: 'application/json' } });
check('reused callback URL → rejected 400', r.status === 400, `${r.status} ${(await r.json()).code}`);

// 3. tampered state (fresh login, state changed in the URL)
const t = browser();
const p = new URL(APP + (await startLogin(t, 'u_ben')));
p.searchParams.set('state', p.searchParams.get('state').slice(0, -2) + 'xx');
const tr = await t.get(p.pathname + p.search, { headers: { accept: 'application/json' } });
check('tampered state → rejected 400', tr.status === 400, `${tr.status} ${(await tr.json()).code}`);

// 4. tampered code (valid state, bad code) → IdP refuses exchange
const c = browser();
const pc = new URL(APP + (await startLogin(c, 'u_ben')));
pc.searchParams.set('code', 'deadbeef');
const cr = await c.get(pc.pathname + pc.search, { headers: { accept: 'application/json' } });
check('tampered code → rejected 401', cr.status === 401, `${cr.status} ${(await cr.json()).code}`);

// 5. browsers get an HTML page with the same status
const h = browser();
const ph = new URL(APP + (await startLogin(h, 'u_ben')));
ph.searchParams.set('state', 'nope');
const hr = await h.get(ph.pathname + ph.search, { headers: { accept: 'text/html' } });
check('browser failure page: 400 + HTML back-link', hr.status === 400 && (await hr.text()).includes('Back to sign in'));

// 6. API authz
const noCookie = await fetch(APP + '/api/conversations?workspace=ws_acme');
check('no cookie → 401', noCookie.status === 401);
const member = await ben.get('/api/conversations?workspace=ws_acme');
check('member workspace → 200', member.status === 200);
const nonMember = await ben.get('/api/conversations?workspace=ws_globex');
check('non-member workspace → 403', nonMember.status === 403, (await nonMember.json()).code);
const unknownWs = await ben.get('/api/conversations?workspace=ws_nope');
check('unknown workspace → 403 (no existence leak)', unknownWs.status === 403);

// 7. WebSocket upgrade
const wsUrl = APP.replace('http', 'ws') + '/ws?workspace=';
const tryWs = (ws, cookie) =>
  new Promise((res) => {
    const s = new WebSocket(wsUrl + ws, { headers: cookie ? { cookie } : {} });
    s.onopen = () => (s.close(), res('open'));
    s.onerror = () => res('refused');
    setTimeout(() => res('timeout'), 4000);
  });
check('ws without session → refused', (await tryWs('ws_acme')) === 'refused');
check('ws non-member → refused', (await tryWs('ws_globex', ben.cookie())) === 'refused');
check('ws member → open', (await tryWs('ws_acme', ben.cookie())) === 'open');

// 8. logout
await ben.get('/auth/logout', { method: 'POST' });
check('after logout → 401', (await ben.get('/api/me')).status === 401);

// 9. grader endpoint untouched by sessions
check('grader without token → 401', (await fetch(APP + '/__grader/reset', { method: 'POST' })).status === 401);

console.log(out.join('\n'));
process.exit(out.some((l) => l.startsWith('FAIL')) ? 1 : 0);

