import type { ConversationDoc, MessageDoc } from '../types/domain.js';

// API shapes (what the React app renders). Documents never leave the server raw.

export const toConversationDto = (c: ConversationDoc) => ({
  contact: c.contact,
  state: c.state,
  assignee: c.assignee,
  lastActivityAt: c.lastActivityAt.toISOString(),
  lastMessage: c.lastMessage ? { text: c.lastMessage.text, dir: c.lastMessage.dir, at: c.lastMessage.at.toISOString() } : null,
});
export type ConversationDto = ReturnType<typeof toConversationDto>;

export const toMessageDto = (m: MessageDoc) => ({
  id: m._id.toHexString(),
  dir: m.dir,
  text: m.text,
  occurredAt: m.occurredAt.toISOString(),
  providerId: m.providerMessageId,
  clientRef: m.clientRef ?? null,
  status: m.status ?? null,
  authorSub: m.authorSub ?? null,
});
export type MessageDto = ReturnType<typeof toMessageDto>;

import { appendEvent } from '../realtime/eventStream.js';
import type { ConversationState, DeliveryStatus, MessageDoc } from '../types/domain.js';
import { newId } from '../utils/ids.js';
import { toMessageDto } from './dto.js';

// Every realtime frame is built here (contract F shapes + extra fields the UI uses).
// Dedupe keys name the FACT, so a retried webhook can never emit it twice.

export const events = {
  inbound: (m: MessageDoc) =>
    appendEvent(m.workspace, `in:${m.providerMessageId}`, {
      type: 'message.inbound',
      contact: m.contact,
      message_id: m.providerMessageId,
      message: toMessageDto(m),
    }),

  outbound: (m: MessageDoc) =>
    appendEvent(m.workspace, `out:${m.clientRef}`, {
      type: 'message.outbound',
      contact: m.contact,
      client_ref: m.clientRef,
      status: m.status,
      message: toMessageDto(m),
    }),

  status: (m: MessageDoc, status: DeliveryStatus) =>
    appendEvent(m.workspace, `st:${m.clientRef}:${status}`, {
      type: 'message.status',
      contact: m.contact,
      client_ref: m.clientRef,
      status,
      message_id: m.providerMessageId,
    }),

  /** Assignments are user actions, never retried by a provider: each one is its own fact. */
  assigned: (workspace: string, contact: string, assignee: string | null) =>
    appendEvent(workspace, `as:${newId('a')}`, { type: 'conversation.assigned', contact, assignee }),

  state: (workspace: string, contact: string, state: ConversationState, factKey = newId('s')) =>
    appendEvent(workspace, `state:${factKey}`, { type: 'conversation.state', contact, state }),
};

import { createHmac, timingSafeEqual } from 'node:crypto';

export type SignatureVerdict = 'ok' | 'invalid' | 'stale';

/**
 * Pigeon: `x-pigeon-signature: t=<unix seconds>,v1=<hex>` where v1 =
 * HMAC-SHA256("<t>.<raw body>", secret). Pure function (tested).
 *  - missing / malformed / mismatching signature -> 'invalid' (401)
 *  - valid signature but |now - t| > tolerance  -> 'stale'   (401, replay)
 * Several v1 values are allowed (secret rotation): any match is enough.
 */
export function verifyPigeonSignature(
  rawBody: Buffer,
  header: string | undefined,
  secret: string,
  nowSeconds: number,
  toleranceSeconds: number,
): SignatureVerdict {
  if (!header || header.length > 1024) return 'invalid';
  let t: number | null = null;
  const v1: string[] = [];
  for (const part of header.split(',')) {
    const i = part.indexOf('=');
    if (i < 0) continue;
    const k = part.slice(0, i).trim();
    const v = part.slice(i + 1).trim();
    if (k === 't' && /^\d{1,12}$/.test(v)) t = Number(v);
    else if (k === 'v1' && /^[0-9a-fA-F]{64}$/.test(v)) v1.push(v.toLowerCase());
  }
  if (t === null || v1.length === 0) return 'invalid';

  const expected = createHmac('sha256', secret).update(`${t}.`).update(rawBody).digest();
  const matches = v1.some((sig) => timingSafeEqual(Buffer.from(sig, 'hex'), expected));
  if (!matches) return 'invalid';

  // Checked after the signature, so a forged request never learns about timing rules.
  return Math.abs(nowSeconds - t) > toleranceSeconds ? 'stale' : 'ok';
}

import { z } from 'zod';

// Pigeon webhook bodies. Unknown fields are ignored (Pigeon may add some).

export const WebhookEnvelope = z.object({
  id: z.string().max(200).optional(),
  type: z.string().min(1).max(100),
  workspace: z.string().min(1).max(128),
  occurred_at: z.string().max(64).optional(),
  data: z.unknown(),
});

export const InboundData = z.object({
  message_id: z.string().min(1).max(200),
  from: z.string().min(1).max(64),
  text: z.string().max(10_000).default(''),
});

export const StatusData = z.object({
  message_id: z.string().max(200).optional(),
  client_ref: z.string().min(1).max(200),
  /** Not an enum on purpose: an unknown future status is ignored with 2xx, not a 400. */
  status: z.string().min(1).max(50),
});

/** occurred_at -> Date; missing/invalid falls back to receipt time (still stored, never rejected). */
export function parseOccurredAt(v: string | undefined, now = new Date()): Date {
  if (!v) return now;
  const t = Date.parse(v);
  return Number.isNaN(t) ? now : new Date(t);
}

