import { conversationRepo, type InboxFilter } from '../repositories/conversation.repo.js';
import type { ConversationDoc } from '../types/domain.js';
import { decodeCursor } from '../utils/cursor.js';

/** API shape of a conversation (what the React app renders). */
export const toConversationDto = (c: ConversationDoc) => ({
  contact: c.contact,
  state: c.state,
  assignee: c.assignee,
  lastActivityAt: c.lastActivityAt.toISOString(),
  lastMessage: c.lastMessage ? { text: c.lastMessage.text, dir: c.lastMessage.dir, at: c.lastMessage.at.toISOString() } : null,
});

export const conversationService = {
  /** Inbox page. `workspace` must already be membership-checked by the caller (requireMember). */
  async list(workspace: string, me: string, q: { filter: InboxFilter; cursor?: string; limit: number }) {
    const page = await conversationRepo.list(workspace, {
      filter: q.filter,
      me,
      cursor: decodeCursor(q.cursor),
      limit: q.limit,
    });
    return { items: page.items.map(toConversationDto), nextCursor: page.nextCursor };
  },
};

