import type { Request, Response } from 'express';
import { WEBHOOK } from '../config/constants.js';
import { env, isKnownWorkspace } from '../config/env.js';
import { logger } from '../infra/logger.js';
import { inboundService } from '../services/inbound.service.js';
import { verifyPigeonSignature } from '../utils/hmac.js';
import { respond } from '../utils/respond.js';
import { isDeliveryStatus } from '../utils/statusRank.js';
import { InboundData, parseOccurredAt, StatusData, WebhookEnvelope } from '../validators/webhook.schema.js';

const ignored = (res: Response, reason: string) => respond.raw(res, 200, { ok: true, ignored: reason });

/**
 * POST /webhooks/pigeon. The answer table in PIGEON.md, in order:
 *   bad/missing signature -> 401 · stale timestamp -> 401 · unparseable -> 400
 *   unknown workspace / unknown type / unknown message -> 2xx (ignored)
 *   stored (or already stored) -> 2xx, only AFTER the write is durable.
 * A 5xx only happens when storage itself fails, which makes Pigeon retry.
 */
export const webhookController = {
  async pigeon(req: Request, res: Response) {
    const raw = req.rawBody ?? Buffer.alloc(0);
    const verdict = verifyPigeonSignature(
      raw,
      req.get('x-pigeon-signature'),
      env.pigeon.webhookSecret,
      Math.floor(Date.now() / 1000),
      WEBHOOK.toleranceSeconds,
    );
    if (verdict === 'invalid') return respond.status(res, 'WEBHOOK_BAD_SIGNATURE');
    if (verdict === 'stale') return respond.status(res, 'WEBHOOK_STALE');

    let json: unknown;
    try {
      json = JSON.parse(raw.toString('utf8'));
    } catch {
      return respond.status(res, 'WEBHOOK_BAD_BODY');
    }
    const envelope = WebhookEnvelope.safeParse(json);
    if (!envelope.success) return respond.status(res, 'WEBHOOK_BAD_BODY');
    const ev = envelope.data;

    if (!isKnownWorkspace(ev.workspace)) return ignored(res, 'unknown workspace');

    switch (ev.type) {
      case 'message.inbound': {
        const data = InboundData.safeParse(ev.data);
        if (!data.success) return respond.status(res, 'WEBHOOK_BAD_BODY');
        await inboundService.messageInbound({
          workspace: ev.workspace,
          eventId: ev.id,
          messageId: data.data.message_id,
          from: data.data.from,
          text: data.data.text,
          occurredAt: parseOccurredAt(ev.occurred_at),
        });
        return respond.raw(res, 200, { ok: true });
      }
      case 'message.status': {
        const data = StatusData.safeParse(ev.data);
        if (!data.success) return respond.status(res, 'WEBHOOK_BAD_BODY');
        if (!isDeliveryStatus(data.data.status)) return ignored(res, 'unknown status');
        const { applied } = await inboundService.messageStatus({
          workspace: ev.workspace,
          clientRef: data.data.client_ref,
          status: data.data.status,
          providerMessageId: data.data.message_id,
        });
        return applied ? respond.raw(res, 200, { ok: true }) : ignored(res, 'not newer or unknown message');
      }
      default:
        logger.debug('webhook type ignored', { type: ev.type });
        return ignored(res, 'unknown type');
    }
  },
};

import { Router } from 'express';
import { webhookController } from '../controllers/webhook.controller.js';
import { rawBody } from '../middleware/rawBody.js';
import { asyncHandler } from '../utils/asyncHandler.js';

export const webhookRoutes = Router();

// Contract C. Raw body (exact signed bytes), mounted before express.json().
webhookRoutes.post('/webhooks/pigeon', ...rawBody, asyncHandler(webhookController.pigeon));

import type { Request, Response } from 'express';
import type { z } from 'zod';
import { conversationService } from '../services/conversation.service.js';
import { replyService } from '../services/reply.service.js';
import { resetService } from '../services/reset.service.js';
import { snapshotService } from '../services/snapshot.service.js';
import { respond } from '../utils/respond.js';
import type { GraderClaimBody, GraderReplyBody } from '../validators/grader.schema.js';

// Contract D. Token-protected (requireGraderToken), never session-protected.
// Every handler calls the SAME services as the UI controllers.
export const graderController = {
  async reset(_req: Request, res: Response) {
    await resetService.resetAll();
    return respond.raw(res, 200, { ok: true });
  },

  async snapshot(_req: Request, res: Response) {
    return respond.raw(res, 200, await snapshotService.build());
  },

  /** 202 once stored; same client_ref twice (even concurrently) is one reply. Unknown workspace -> 404. */
  async reply(req: Request, res: Response) {
    const b = req.body as z.infer<typeof GraderReplyBody>;
    const m = await replyService.create({ workspace: b.workspace, contact: b.contact, text: b.text, clientRef: b.client_ref, authorSub: null });
    return respond.raw(res, 202, { ok: true, client_ref: m.clientRef, status: m.status });
  },

  /** 200 if this agent now holds it (or already did), 409 if someone else does. */
  async claim(req: Request, res: Response) {
    const b = req.body as z.infer<typeof GraderClaimBody>;
    const r = await conversationService.claim(b.workspace, b.contact, b.agent);
    return respond.raw(res, r.status === 'taken' ? 409 : 200, { ok: r.status !== 'taken', assignee: r.conversation.assignee });
  },
};

import { Router } from 'express';
import { graderController } from '../controllers/grader.controller.js';
import { requireGraderToken } from '../middleware/requireGraderToken.js';
import { validate } from '../middleware/validate.js';
import { asyncHandler } from '../utils/asyncHandler.js';
import { GraderClaimBody, GraderReplyBody } from '../validators/grader.schema.js';

export const graderRoutes = Router();

graderRoutes.use('/__grader', requireGraderToken);
graderRoutes.post('/__grader/reset', asyncHandler(graderController.reset));
graderRoutes.get('/__grader/snapshot', asyncHandler(graderController.snapshot));
graderRoutes.post('/__grader/reply', validate({ body: GraderReplyBody }), asyncHandler(graderController.reply));
graderRoutes.post('/__grader/claim', validate({ body: GraderClaimBody }), asyncHandler(graderController.claim));

import type { Request, Response } from 'express';
import { conversationService } from '../services/conversation.service.js';
import { toMessageDto } from '../services/dto.js';
import { replyService } from '../services/reply.service.js';
import { AppError } from '../utils/AppError.js';
import { respond } from '../utils/respond.js';
import type { ListConversationsQuery, MessagesQuery, ReplyBody } from '../validators/conversation.schema.js';

// All routes run behind requireSession + requireMember, so req.user and
// req.workspace (id + caller's role) are set and trusted.

export const conversationController = {
  /** GET /api/conversations?workspace=&filter=&cursor=&limit= (contract E). */
  async list(req: Request, res: Response) {
    const q = req.query as unknown as ListConversationsQuery;
    const page = await conversationService.list(req.workspace!.id, req.user!.sub, q);
    return respond.ok(res, 'CONVERSATIONS_LISTED', { items: page.items }, { meta: { nextCursor: page.nextCursor } });
  },

  /** GET /api/conversations/:contact?workspace= */
  async get(req: Request, res: Response) {
    return respond.ok(res, 'OK', await conversationService.get(req.workspace!.id, req.params.contact));
  },

  /** GET /api/conversations/:contact/messages?workspace=&before=&limit= (oldest first; prevCursor walks back). */
  async messages(req: Request, res: Response) {
    const q = req.query as unknown as MessagesQuery;
    const page = await conversationService.messages(req.workspace!.id, req.params.contact, q);
    return respond.ok(res, 'MESSAGES_LISTED', { items: page.items }, { meta: { prevCursor: page.prevCursor } });
  },

  /** POST /api/conversations/:contact/replies?workspace=  { text, client_ref } -> 202 once stored. */
  async reply(req: Request, res: Response) {
    const b = req.body as ReplyBody;
    const m = await replyService.createAsAgent({
      workspace: req.workspace!.id,
      contact: req.params.contact,
      text: b.text,
      clientRef: b.client_ref,
      sub: req.user!.sub,
      role: req.workspace!.role,
    });
    return respond.ok(res, 'REPLY_QUEUED', toMessageDto(m));
  },

  /** POST /api/conversations/:contact/:action?workspace=  (claim | release | close | reopen) */
  async act(req: Request, res: Response) {
    const ws = req.workspace!;
    const sub = req.user!.sub;
    const contact = req.params.contact;
    switch (req.params.action) {
      case 'claim': {
        const r = await conversationService.claim(ws.id, contact, sub, { takeOver: ws.role === 'admin' });
        if (r.status === 'taken') throw new AppError('CONVERSATION_TAKEN');
        return respond.ok(res, 'CONVERSATION_CLAIMED', r.conversation);
      }
      case 'release':
        return respond.ok(res, 'CONVERSATION_RELEASED', await conversationService.release(ws.id, contact, sub, ws.role));
      case 'close':
        return respond.ok(res, 'CONVERSATION_CLOSED', await conversationService.setState(ws.id, contact, 'closed', sub, ws.role));
      case 'reopen':
        return respond.ok(res, 'CONVERSATION_REOPENED', await conversationService.setState(ws.id, contact, 'open', sub, ws.role));
      default:
        throw new AppError('ROUTE_NOT_FOUND');
    }
  },
};

