import type { IncomingMessage, Server } from 'node:http';
import type { Duplex } from 'node:stream';
import { WebSocketServer, type WebSocket } from 'ws';
import { SESSION } from '../config/constants.js';
import { logger } from '../infra/logger.js';
import { membershipOf } from '../middleware/requireMember.js';
import { sessionService } from '../services/session.service.js';
import type { SessionUser } from '../types/express.js';
import { parseCookieHeader } from '../utils/cookies.js';

// GET /ws?workspace=<id>[&after=<seq>] (contract F).
// Authentication happens BEFORE the upgrade: without a session, or for a
// workspace the user is not a member of, the handshake is refused with a
// plain HTTP 401/403 and no socket is ever opened.
// Live fan-out and ?after= replay are added in the realtime phase.

export interface ClientSocket extends WebSocket {
  user: SessionUser;
  workspace: string;
  after: number | null;
}

/** Sockets per workspace on THIS instance (the realtime phase fans out to them). */
export const socketsByWorkspace = new Map<string, Set<ClientSocket>>();

function refuse(socket: Duplex, status: 401 | 403 | 400, reason: string) {
  socket.end(`HTTP/1.1 ${status} ${reason}\r\nConnection: close\r\nContent-Length: 0\r\n\r\n`);
}

export function attachWebSocketGateway(server: Server): () => Promise<void> {
  const wss = new WebSocketServer({ noServer: true, maxPayload: 16 * 1024 });

  server.on('upgrade', (req: IncomingMessage, socket: Duplex, head: Buffer) => {
    const url = new URL(req.url ?? '/', 'http://internal');
    if (url.pathname !== '/ws') return refuse(socket, 400, 'Bad Request');

    void (async () => {
      const sid = parseCookieHeader(req.headers.cookie)[SESSION.cookieName];
      const user = await sessionService.get(sid);
      if (!user) return refuse(socket, 401, 'Unauthorized');

      const workspace = url.searchParams.get('workspace');
      if (!membershipOf(user, workspace)) return refuse(socket, 403, 'Forbidden');

      const afterRaw = url.searchParams.get('after');
      const after = afterRaw !== null && /^\d+$/.test(afterRaw) ? Number(afterRaw) : null;

      wss.handleUpgrade(req, socket, head, (ws) => {
        const client = Object.assign(ws, { user, workspace: workspace!, after }) as ClientSocket;
        const set = socketsByWorkspace.get(client.workspace) ?? new Set<ClientSocket>();
        set.add(client);
        socketsByWorkspace.set(client.workspace, set);
        ws.on('close', () => set.delete(client));
        ws.on('error', () => set.delete(client));
        logger.debug('ws open', { sub: user.sub, workspace: client.workspace, after });
      });
    })().catch((err) => {
      logger.warn('ws upgrade failed', { err });
      socket.destroy();
    });
  });

  return async () => {
    for (const set of socketsByWorkspace.values()) for (const ws of set) ws.close(1001, 'server shutting down');
    await new Promise<void>((r) => wss.close(() => r()));
  };
}

